function sanitizeSignupAnalyticsProperties(value = {}) {
  const input = value && typeof value === "object" ? value : {};
  const output = {};
  for (const [key, raw] of Object.entries(input)) {
    if (!allowedSignupAnalyticsProperties.has(key)) continue;
    if (typeof raw === "boolean") output[key] = raw;
    else if (typeof raw === "number") output[key] = Number.isFinite(raw) ? raw : 0;
    else output[key] = clean(raw).slice(0, 80);
  }
  return output;
}

export function isAnalyticsSchemaMismatch(error) {
  return error?.code === "PGRST204" || error?.code === "42703";
}

export function analyticsEventInsertPayloads(row) {
  return [
    {
      event_type: row.event_type,
      user_id: null,
      metadata: row.properties,
      created_at: row.created_at
    },
    {
      event_type: row.event_type,
      user_id: null,
      profile_key: row.profile_key,
      metadata: row.properties,
      created_at: row.created_at
    },
    {
      event_type: row.event_type,
      profile_key: row.profile_key,
      restaurant_id: row.restaurant_id,
      entity_type: row.entity_type,
      entity_id: row.entity_id,
      properties: row.properties,
      created_at: row.created_at
    }
  ];
}

async function insertAnalyticsEvent(row) {
  let lastSchemaError = null;
  for (const body of analyticsEventInsertPayloads(row)) {
    try {
      return await supabaseFetch("/rest/v1/analytics_events?select=*", {
        method: "POST",
        service: true,
        headers: { Prefer: "return=representation" },
        body
      });
    } catch (error) {
      if (!isAnalyticsSchemaMismatch(error)) throw error;
      lastSchemaError = error;
    }
  }
  throw lastSchemaError || new Error("Analytics storage is unavailable.");
}

async function analyticsEvent(method, body) {
  if (method !== "POST") return json(405, { error: "Method not allowed." });
  const eventType = clean(body.event_type || body.eventType);
  if (!allowedSignupAnalyticsEvents.has(eventType)) return json(400, { error: "Unsupported analytics event." });
  const properties = sanitizeSignupAnalyticsProperties(body.metadata || body.properties || {});
  if (anonymousPublicAnalyticsEvents.has(eventType) && (!properties.path?.startsWith("/") || /[?#]/.test(properties.path))) {
    return json(400, { error: "A safe public website path is required." });
  }
  const bookingRestaurantId = eventType === "restaurant_booking_options_viewed" ? clean(properties.restaurant_id) : "";
  if (eventType === "restaurant_booking_options_viewed") {
    if (!looksLikeUuid(bookingRestaurantId) || !bookingOptionAnalyticsEntryPoints.has(clean(properties.entry_point))) {
      return json(400, { error: "A valid public restaurant interaction is required." });
    }
    if (!supabaseConfigured) {
      ensureDemo();
      const publicRestaurant = demo.restaurants.find((item) => clean(item.id) === bookingRestaurantId
        && clean(item.status) === "approved"
        && item.visible_on_guest_site !== false);
      if (!publicRestaurant) return json(400, { error: "A valid public restaurant interaction is required." });
    } else {
      const publicRestaurants = await supabaseFetch(`/rest/v1/public_restaurant_cards?select=restaurant_id&restaurant_id=eq.${encodeURIComponent(bookingRestaurantId)}&limit=1`, { service: false });
      if (!publicRestaurants?.length) return json(400, { error: "A valid public restaurant interaction is required." });
    }
  }
  const row = {
    id: crypto.randomUUID(),
    event_type: eventType,
    profile_key: anonymousPublicAnalyticsEvents.has(eventType) ? null : aiProfileKey(body.profile_key),
    restaurant_id: bookingRestaurantId || null,
    entity_type: eventType === "guest_website_view"
      ? "guest_website"
      : eventType === "restaurant_booking_options_viewed"
        ? "restaurant"
      : eventType.startsWith("signup_") || ["preference_selected", "terms_accepted", "privacy_accepted", "restaurant_followed_during_signup"].includes(eventType)
        ? "guest_signup"
        : "guest_account",
    entity_id: bookingRestaurantId || null,
    properties,
    created_at: nowIso()
  };

  if (!supabaseConfigured) {
    ensureDemo();
    demo.analyticsEvents.unshift(row);
    return json(201, { mode: "demo", event: row });
  }

  const rows = await insertAnalyticsEvent(row);
  const saved = rows?.[0] ? {
    ...rows[0],
    properties: rows[0].properties || rows[0].metadata || row.properties
  } : null;
  return json(201, { mode: "supabase", event: saved });
}

function normalizeGuestPreferencePatch(existing = {}, body = {}, preferredLanguage = "en") {
  const merged = { ...(existing || {}) };
  const arrayFields = [
    "cuisines", "food_categories", "drink_preferences", "dietary_needs", "atmospheres", "dining_experiences",
    "companions", "preferred_days", "preferred_time_windows", "discount_levels", "selection_priorities",
    "favorite_restaurants", "excluded_categories", "notification_preferences", "notification_channels", "preferred_neighborhoods"
  ];
  const textFields = [
    "allergy_notes", "custom_cuisine", "party_size", "booking_lead_time", "dining_duration", "spending_range",
    "consider_no_discount_match", "discovery_preference", "new_restaurant_recommendations",
    "new_menu_item_recommendations", "notification_frequency", "event_recommendations_interest",
    "future_calendar_interest", "sms_country_code", "sms_phone_number"
  ];
  for (const field of arrayFields) {
    if (body[field] !== undefined) merged[field] = arrayFrom(body[field]);
  }
  if (body.companions !== undefined) {
    merged.companions = arrayFrom(body.companions).map((item) => /^(alone|single\s*\/\s*solo)$/i.test(clean(item)) ? "Single / Solo" : item);
  }
  if (body.preferred_neighborhoods !== undefined && arrayFrom(body.preferred_neighborhoods).some((item) => clean(item).toLowerCase() === "no preference")) {
    merged.preferred_neighborhoods = ["No preference"];
  }
  for (const field of textFields) {
    if (body[field] !== undefined) merged[field] = clean(body[field]);
  }
  if (body.location && typeof body.location === "object") merged.location = { ...(merged.location || {}), ...body.location };
  const flatLocation = {
    country: clean(body.country || body.country_code),
    country_code: clean(body.country_code || body.country),
    state: clean(body.state || body.region || body.state_region),
    state_region: clean(body.state_region || body.region || body.state),
    region: clean(body.region || body.state_region || body.state),
    city: clean(body.city),
    city_normalized: clean(body.city_normalized || body.city),
    postal_code: clean(body.postal_code || body.zip),
    max_travel_distance_value: Math.max(0, numberOr(body.max_travel_distance_value || body.travel_distance_value, 0)),
    travel_distance_unit: clean(body.travel_distance_unit),
    max_travel_distance_miles: Math.max(0, numberOr(body.max_travel_distance_miles || body.travel_distance_miles, 0)),
    transportation_method: clean(body.transportation_method)
  };
  if (Object.values(flatLocation).some(Boolean)) {
    merged.location = {
      ...(merged.location || {}),
      ...Object.fromEntries(Object.entries(flatLocation).filter(([, value]) => Boolean(value)))
    };
  }
  const smsDestination = normalizePhoneE164(`${merged.sms_country_code || ""}${merged.sms_phone_number || ""}`);
  if (body.sms_consent !== undefined) {
    const smsSelected = arrayFrom(merged.notification_channels).includes("SMS");
    const sms = boolValue(body.sms_consent) && smsSelected && isValidE164Phone(smsDestination);
    merged.consents = {
      ...(merged.consents || {}),
      sms,
      sms_opted_in: sms,
      sms_consent_at: sms ? nowIso() : null,
      language: normalizeLanguage(body.preferred_language || preferredLanguage)
    };
  }
  if (body.marketing_consent !== undefined) {
    const marketing = boolValue(body.marketing_consent);
    merged.consents = {
      ...(merged.consents || {}),
      marketing,
      marketing_accepted_at: marketing ? nowIso() : null,
      language: normalizeLanguage(body.preferred_language || preferredLanguage)
    };
  }
  merged.minimumInterestingDiscount = minimumInterestingDiscountFromLevels(merged.discount_levels);
  merged.minimum_interesting_discount = merged.minimumInterestingDiscount;
  return merged;
}

function validateGuestPreferenceProfile(preferences = {}) {
  if (arrayFrom(preferences.cuisines).includes("Other") && !clean(preferences.custom_cuisine)) return "custom_cuisine is required.";
  if (arrayFrom(preferences.notification_channels).includes("SMS")) {
    const smsDestination = normalizePhoneE164(`${preferences.sms_country_code || ""}${preferences.sms_phone_number || ""}`);
    if (!preferences.consents?.sms || !isValidE164Phone(smsDestination)) return "Valid SMS phone number and consent are required.";
  }
  return "";
}

function textBag(...values) {
  return values.flat().map((value) => clean(value).toLowerCase()).filter(Boolean).join(" ");
}

function includesAny(haystack, needles = []) {
  const text = clean(haystack).toLowerCase();
  return needles.some((needle) => text.includes(clean(needle).toLowerCase()));
}

function smartDiscountForRestaurant(restaurant, preferences = {}, score = 0) {
  if (restaurant.ai_discount_enabled === false) return 0;
  const range = discountRangeValue(preferences.preferred_discount_range);
  const minAllowed = Math.max(0, numberOr(restaurant.min_discount_percent, 10));
  const maxAllowed = Math.max(minAllowed, numberOr(restaurant.max_discount_percent, restaurant.highest_discount || 0));
  if (!maxAllowed) return 0;

  let target = Math.max(minAllowed, range.min || minAllowed);
  if (score < 55) target += 10;
  else if (score < 72) target += 5;
  if (restaurant.offer_count < 1) target = Math.min(target, minAllowed);
  return Math.min(maxAllowed, Math.max(minAllowed, Math.round(target / 5) * 5));
}

function scoreRestaurantForPreferences(restaurant, preferences = {}) {
  let score = 30;
  const reasons = [];
  const cuisineText = textBag(restaurant.cuisine, restaurant.cuisine_type);
  const descriptiveText = textBag(restaurant.restaurant_description, restaurant.description, restaurant.restaurant_name, restaurant.district, restaurant.address);

  if (includesAny(cuisineText, preferences.cuisines)) {
    score += 18;
    reasons.push("Cuisine match");
  }
  if (includesAny(descriptiveText, preferences.food_interests)) {
    score += 14;
    reasons.push("Food interest match");
  }
  if (includesAny(descriptiveText, preferences.atmospheres)) {
    score += 10;
    reasons.push("Atmosphere match");
  }
  if (includesAny(textBag(restaurant.district, restaurant.address), preferences.preferred_neighborhoods)) {
    score += 12;
    reasons.push("Preferred neighborhood");
  }
  if ((preferences.favorite_restaurants || []).some((name) => clean(restaurant.restaurant_name).toLowerCase().includes(clean(name).toLowerCase()))) {
    score += 18;
    reasons.push("Favorite restaurant signal");
  }

  score += Math.min(12, numberOr(restaurant.overall_rating_avg, restaurant.rating || 0) * 2);
  score += Math.min(8, numberOr(restaurant.favorites_count, 0));
  if (restaurant.offer_count > 0) {
    score += 6;
    reasons.push("Available SmartTable offer");
  }
  if (preferences.outdoor_seating && restaurant.outdoor_seating) {
    score += 7;
    reasons.push("Outdoor seating match");
  }
  if (preferences.kids_friendly && restaurant.kids_friendly) {
    score += 7;
    reasons.push("Kids friendly match");
  }
  if (preferences.parking_required && restaurant.parking_available) {
    score += 6;
    reasons.push("Parking available");
  }
  if (preferences.subway_preferred && includesAny(textBag(restaurant.address, restaurant.district), ["Village", "Soho", "Nolita", "Midtown", "Brooklyn"])) {
    score += 4;
    reasons.push("Transit-friendly area");
  }
  if (!reasons.length) reasons.push("Strong overall quality and location fit");

  return {
    score: Math.max(1, Math.min(99, Math.round(score))),
    reasons
  };
}

function recommendationRow(restaurant, preferences = {}) {
  const scoring = scoreRestaurantForPreferences(restaurant, preferences);
  const smartDiscount = smartDiscountForRestaurant(restaurant, preferences, scoring.score);
  const travelDistance = numberOr(preferences.travel_distance_miles, 2.5);
  const travelEstimate = Math.max(8, Math.round(numberOr(restaurant.average_service_minutes, 75) / 12 + travelDistance * 6));
  const bestTime = (preferences.preferred_times || [])[0] || (preferences.preferred_time_windows || [])[0] || "Early dinner window";
  const diningDuration = numberOr(restaurant.average_service_minutes, 75);
  const humanReason = `Recommended because it matches ${scoring.reasons.slice(0, 3).join(", ").toLowerCase()}, fits your preferred timing, and keeps travel practical for your dining plan.`;
  return {
    ...restaurant,
    ai_match_score: scoring.score,
    ai_reasons: scoring.reasons,
    why_recommended: humanReason,
    travel_estimate: `${travelEstimate} min estimated travel`,
    best_time_to_reserve: bestTime,
    estimated_dining_duration: `${diningDuration} min`,
    available_offer_label: restaurant.first_offer_id
      ? `${restaurant.highest_discount || smartDiscount || 0}% SmartTable offer available`
      : "No active discount needed for this match",
    matching_preferences: scoring.reasons,
    recommended_discount_percent: smartDiscount,
    smart_discount_explanation: smartDiscount
      ? `Offer starts at ${smartDiscount}% based on conversion likelihood and restaurant guardrails.`
      : "Recommended on fit and quality even without an active discount."
  };
}

function hourFromTime(value) {
  const match = clean(value).match(/^(\d{1,2})/);
  const hour = match ? Number(match[1]) : 19;
  return Number.isFinite(hour) ? Math.max(0, Math.min(23, hour)) : 19;
}

function dayOfWeekFromDate(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return new Date().getDay();
  return date.getDay();
}

function timeOfDayBucket(time) {
  const hour = hourFromTime(time);
  if (hour < 11) return "breakfast";
  if (hour < 15) return "lunch";
  if (hour < 18) return "afternoon";
  if (hour < 22) return "dinner";
  return "late_night";
}

function observedDurationsForRestaurant(restaurantId) {
  ensureDemo();
  return demo.aiServiceTimeObservations
    .filter((item) => item.restaurant_id === restaurantId && Number.isFinite(Number(item.visit_duration_minutes)))
    .map((item) => Number(item.visit_duration_minutes));
}

function estimateServiceTime(restaurant, input = {}, observedDurations = []) {
  const partySize = Math.max(1, Math.trunc(numberOr(input.party_size || input.preferred_party_size, 2)));
  const mealCategory = clean(input.meal_category || timeOfDayBucket(input.reservation_time)).toLowerCase();
  const bucket = timeOfDayBucket(input.reservation_time);
  const day = dayOfWeekFromDate(input.reservation_date);
  const restaurantType = clean(input.restaurant_type || restaurant.restaurant_type || restaurant.cuisine_type || restaurant.cuisine || "restaurant").toLowerCase();
  const observedAverage = average(observedDurations);
  let minutes = observedAverage || numberOr(restaurant.average_service_minutes, 75);

  if (restaurantType.includes("fine") || restaurantType.includes("luxury")) minutes += 22;
  if (restaurantType.includes("casual") || restaurantType.includes("quick")) minutes -= 8;
  if (mealCategory.includes("drink") || mealCategory.includes("bar")) minutes -= 25;
  if (mealCategory.includes("dessert") || mealCategory.includes("coffee")) minutes -= 30;
  if (mealCategory.includes("brunch")) minutes += 8;
  if (mealCategory.includes("tasting")) minutes += 45;
  if (bucket === "dinner") minutes += 10;
  if (bucket === "late_night") minutes -= 6;
  if (day === 0 || day === 5 || day === 6) minutes += 8;
  minutes += Math.max(0, partySize - 2) * 8;

  const estimate = Math.max(35, Math.min(240, Math.round(minutes / 5) * 5));
  return {
    estimated_duration_minutes: estimate,
    confidence: observedDurations.length >= 12 ? "learned" : observedDurations.length >= 3 ? "blended" : "directional",
    inputs: {
      party_size: partySize,
      meal_category: mealCategory || bucket,
      time_of_day: bucket,
      day_of_week: day,
      restaurant_type: restaurantType,
      observed_visits: observedDurations.length
    }
  };
}

function routeMinutes(miles, mode) {
  const distance = Math.max(0, numberOr(miles, 0));
  const speeds = { walking: 3, driving: 14, transit: 10, rideshare: 13 };
  const speed = speeds[clean(mode)] || speeds.driving;
  return Math.ceil((distance / speed) * 60);
}

function analyzeConsumptionSignals(body = {}, restaurant = {}) {
  const text = textBag(body.description, body.short_review, body.liked_highlight, body.image_url, body.media_type, restaurant.cuisine_type, restaurant.cuisine);
  const categories = [
    "steak", "pizza", "burger", "sushi", "cocktail", "wine", "beer", "dessert", "coffee", "pasta", "seafood", "salad", "taco", "ramen"
  ];
  const labels = categories.filter((item) => text.includes(item));
  const drinkLabels = labels.filter((item) => ["cocktail", "wine", "beer", "coffee"].includes(item));
  const foodLabels = labels.filter((item) => !drinkLabels.includes(item));
  const cuisine = clean(restaurant.cuisine_type || restaurant.cuisine || body.cuisine || "unknown");
  const rating = numberOr(body.rating, 0);
  const words = clean(`${body.description || ""} ${body.short_review || ""} ${body.liked_highlight || ""}`).toLowerCase();
  const flavorProfile = [
    words.includes("spicy") ? "spicy" : "",
    words.includes("sweet") ? "sweet" : "",
    words.includes("fresh") ? "fresh" : "",
    words.includes("smoky") ? "smoky" : "",
    words.includes("rich") ? "rich" : ""
  ].filter(Boolean);
  const ingredientHints = {
    steak: ["beef", "salt", "pepper"],
    pizza: ["dough", "tomato", "cheese"],
    burger: ["beef", "bun", "cheese"],
    sushi: ["rice", "fish", "seaweed"],
    pasta: ["pasta", "sauce", "herbs"],
    seafood: ["seafood", "lemon", "herbs"],
    dessert: ["cream", "sugar"],
    cocktail: ["spirit", "citrus"],
    wine: ["grapes"],
    beer: ["malt", "hops"],
    coffee: ["coffee beans"]
  };
  const ingredients = [...new Set(labels.flatMap((label) => ingredientHints[label] || [label]))];
  const detectedDish = foodLabels[0] || (clean(body.media_type) === "food" ? labels[0] || "chef_special" : null);
  const detectedDrink = drinkLabels[0] || (clean(body.media_type) === "drink" ? labels[0] || "house_drink" : null);
  const presentationScore = Math.max(35, Math.min(100, 55 + labels.length * 6 + rating * 6 + (clean(body.image_url) ? 4 : 0)));
  return {
    ai_labels: labels.length ? labels : [clean(body.media_type || "dining")],
    food_type: detectedDish,
    drink_type: detectedDrink,
    cuisine,
    detected_dish: detectedDish,
    detected_drink: detectedDrink,
    cuisine_category: cuisine,
    ingredients,
    flavor_profile: flavorProfile.length ? flavorProfile : [detectedDrink ? "balanced" : "savory"],
    presentation_score: Math.round(presentationScore),
    price_perception: words.includes("expensive") ? "expensive" : words.includes("great value") || words.includes("worth") ? "good_value" : "unknown",
    popularity_signal: Math.max(1, Math.min(100, 35 + labels.length * 8 + rating * 8)),
    provider: "rules_engine",
    status: "placeholder_ready_for_ai_image_recognition"
  };
}

function calculateFeedbackPoints(submission = {}) {
  let points = 0;
  const hasRatings = [submission.rating, submission.overall_rating, submission.food_rating, submission.service_rating, submission.ambience_rating]
    .some((value) => numberOr(value, 0) >= 1);
  if (hasRatings) points += 25;
  if (clean(submission.short_review).length > 8) points += 25;
  if (clean(submission.image_url)) points += 50;
  if (clean(submission.description).length > 8 || clean(submission.liked_highlight).length > 8) points += 20;
  if (clean(submission.ordered_items).length > 1 || clean(submission.what_did_you_order).length > 1) points += 20;
  if (clean(submission.would_recommend)) points += 10;
  if (clean(submission.would_return)) points += 10;
  return Math.min(160, points);
}

function loyaltyForUpload(body = {}) {
  return calculateFeedbackPoints(body);
}

const loyaltyBadgeRules = [
  { key: "food_explorer", label: "Food Explorer", target: 50, test: ({ points }) => points },
  { key: "steak_master", label: "Steak Master", target: 1, test: ({ labels }) => labels.has("steak") ? 1 : 0 },
  { key: "sushi_hunter", label: "Sushi Hunter", target: 1, test: ({ labels }) => labels.has("sushi") ? 1 : 0 },
  { key: "wine_lover", label: "Wine Lover", target: 1, test: ({ labels }) => labels.has("wine") ? 1 : 0 },
  { key: "cocktail_expert", label: "Cocktail Expert", target: 1, test: ({ labels }) => labels.has("cocktail") ? 1 : 0 },
  { key: "nyc_food_hunter", label: "NYC Food Hunter", target: 3, test: ({ restaurantCount }) => restaurantCount },
  { key: "trend_spotter", label: "Trend Spotter", target: 5, test: ({ uniqueLabels }) => uniqueLabels }
];

function loyaltyStatus(account = {}, uploads = []) {
  const points = Math.max(0, numberOr(account.lifetime_points ?? account.points_balance, 0));
  const labels = new Set(uploads.flatMap((upload) => arrayFrom(upload.ai_labels).map((label) => clean(label).toLowerCase()).filter(Boolean)));
  const restaurantCount = new Set(uploads.map((upload) => upload.restaurant_id).filter(Boolean)).size;
  const context = { points, labels, restaurantCount, uniqueLabels: labels.size };
  const badges = loyaltyBadgeRules.map((rule) => {
    const current = Math.min(rule.target, Math.max(0, numberOr(rule.test(context), 0)));
    return {
      key: rule.key,
      label: rule.label,
      current,
      target: rule.target,
      progress_percent: Math.round((current / rule.target) * 100),
      unlocked: current >= rule.target
    };
  });
  return {
    points_balance: Math.max(0, numberOr(account.points_balance, points)),
    lifetime_points: points,
    completed_reviews: numberOr(account.completed_reviews, uploads.filter((upload) => upload.short_review || upload.rating).length),
    uploaded_photos: numberOr(account.uploaded_photos, uploads.filter((upload) => clean(upload.image_url)).length),
    last_reward_date: account.last_reward_date || uploads[0]?.created_at || null,
    badges,
    unlocked_badges: badges.filter((badge) => badge.unlocked),
    next_badge: badges.find((badge) => !badge.unlocked) || null
  };
}

function topCounts(values, limit = 6) {
  const counts = new Map();
  for (const value of values.flatMap((item) => arrayFrom(item))) {
    const key = clean(value).toLowerCase();
    if (key) counts.set(key, (counts.get(key) || 0) + 1);
  }
  return [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([label, count]) => ({ label, count }));
}

function consumptionTrendBreakdown(uploads = []) {
  return {
    top_dishes: topCounts(uploads.map((upload) => upload.detected_dish || upload.food_type).filter(Boolean)),
    fastest_growing_dishes: topCounts(uploads.map((upload) => upload.detected_dish || upload.food_type).filter(Boolean)),
    most_uploaded_drinks: topCounts(uploads.map((upload) => upload.detected_drink || upload.drink_type).filter(Boolean)),
    most_photographed_foods: topCounts(uploads.map((upload) => upload.detected_dish || upload.food_type || upload.media_type).filter(Boolean)),
    popular_ingredients: topCounts(uploads.map((upload) => upload.ingredients || [])),
    flavor_profiles: topCounts(uploads.map((upload) => upload.flavor_profile || [])),
    uploaded_photo_count: uploads.filter((upload) => clean(upload.image_url)).length,
    average_upload_rating: average(uploads.map((upload) => numberOr(upload.rating, 0)).filter(Boolean))
  };
}

function upsertDemoLoyalty(profileKey, points, metadata = {}) {
  ensureDemo();
  const key = aiProfileKey(profileKey);
  let account = demo.loyaltyAccounts.find((item) => item.profile_key === key);
  if (!account) {
    account = {
      id: crypto.randomUUID(),
      profile_key: key,
      points_balance: 0,
      lifetime_points: 0,
      completed_reviews: 0,
      uploaded_photos: 0,
      last_reward_date: null,
      created_at: nowIso(),
      updated_at: nowIso()
    };
    demo.loyaltyAccounts.unshift(account);
  }
  account.points_balance += points;
  account.lifetime_points += points;
  account.completed_reviews = numberOr(account.completed_reviews, 0) + (metadata.completedReview ? 1 : 0);
  account.uploaded_photos = numberOr(account.uploaded_photos, 0) + (metadata.uploadedPhoto ? 1 : 0);
  account.last_reward_date = nowIso();
  account.updated_at = nowIso();
  return account;
}

function restaurantIntelligenceSummary(restaurantId = null) {
  ensureDemo();
  const uploads = demo.consumptionUploads.filter((item) => !restaurantId || item.restaurant_id === restaurantId);
  const reservations = demo.reservations.filter((item) => !restaurantId || item.restaurant_id === restaurantId);
  const reviews = demo.restaurantReviews.filter((item) => (!restaurantId || item.restaurant_id === restaurantId) && item.status === "approved");
  const followers = demo.restaurantFollowers.filter((item) => !restaurantId || item.restaurant_id === restaurantId);
  const durations = restaurantId
    ? observedDurationsForRestaurant(restaurantId)
    : demo.aiServiceTimeObservations.map((item) => Number(item.visit_duration_minutes)).filter(Number.isFinite);
  const labelCounts = new Map();
  for (const upload of uploads) {
    for (const label of arrayFrom(upload.ai_labels)) {
      const key = clean(label || "unknown");
      if (key) labelCounts.set(key, (labelCounts.get(key) || 0) + 1);
    }
  }
  const topLabels = [...labelCounts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 8)
    .map(([label, count]) => ({ label, count }));
  const uploadRatings = uploads.map((item) => numberOr(item.rating, 0)).filter(Boolean);
  const reviewRatings = reviews.map((item) => (numberOr(item.food_rating, 0) + numberOr(item.service_rating, 0) + numberOr(item.ambience_rating, 0)) / 3);
  const trendBreakdown = consumptionTrendBreakdown(uploads);
  return {
    restaurant_id: restaurantId,
    uploads_total: uploads.length,
    photos_total: uploads.filter((item) => clean(item.image_url)).length,
    uploaded_photo_count: trendBreakdown.uploaded_photo_count,
    loyalty_points_awarded: uploads.reduce((sum, item) => sum + numberOr(item.loyalty_points_awarded, 0), 0),
    reservations_total: reservations.length,
    returning_customer_rate: reservations.length ? Math.round((new Set(reservations.map((item) => item.guest_email).filter(Boolean)).size / reservations.length) * 100) : 0,
    followers_total: followers.length,
    average_dining_duration: average(durations) || null,
    satisfaction_score: average(reviewRatings.length ? reviewRatings : uploadRatings),
    upload_satisfaction_score: average(uploadRatings),
    top_trends: topLabels,
    ...trendBreakdown,
    highest_rated_menu_categories: topCounts(uploads.filter((item) => numberOr(item.rating, 0) >= 4.5).map((item) => item.detected_dish || item.food_type || item.detected_drink || item.drink_type || item.media_type)),
    value_perception_signals: uploads.some((item) => clean(item.price_perception) === "good_value") ? "Strong value perception" : "Not enough value-perception signal yet",
    image_recognition_status: "placeholder_ready_for_future_ai",
    privacy: "aggregated_anonymized_no_pii"
  };
}

function enhancedDemandForecast(restaurant, metrics = {}) {
  const views = Math.max(0, numberOr(metrics.views, restaurant?.views_count || 0));
  const bookings = Math.max(0, numberOr(metrics.bookings ?? metrics.reservations, 0));
  const importedReservations = Math.max(0, numberOr(metrics.imported_reservations, 0));
  const manualReservations = Math.max(0, numberOr(metrics.manual_reservations, 0));
  const supplementalDemand = Math.min(18, Math.round(importedReservations * 1.4 + manualReservations * 0.9));
  const activeOffers = Math.max(0, numberOr(metrics.active_offers, 0));
  const accepted = Math.max(0, numberOr(metrics.accepted, 0));
  const reservationValueEstimate = Math.max(35, numberOr(metrics.reservation_value_estimate, 85));
  const minDiscount = Math.max(0, numberOr(restaurant?.min_discount_percent, 10));
  const maxDiscount = Math.max(minDiscount, numberOr(restaurant?.max_discount_percent, 30));
  let demandScore = Math.min(100, Math.max(0, 28 + bookings * 16 + activeOffers * 8 + Math.min(22, views * 2) + accepted * 6 + supplementalDemand));
  if (views < 6 && bookings === 0 && importedReservations === 0 && manualReservations === 0) demandScore = Math.min(demandScore, 38);
  if (activeOffers > 0 && bookings > 0) demandScore = Math.max(demandScore, 52);

  const suggestedDiscount = demandScore < 40
    ? Math.min(maxDiscount, Math.max(20, minDiscount))
    : demandScore > 78
      ? Math.min(10, minDiscount)
      : activeOffers > 0
        ? Math.round((minDiscount + Math.min(maxDiscount, 20)) / 2)
        : Math.min(maxDiscount, Math.max(minDiscount, 15));
  const suggestedAction = activeOffers > 0 && demandScore >= 45
    ? "hold_current_strategy"
    : demandScore < 45
      ? "create_suggested_offer"
      : demandScore > 78
        ? "reduce_discount_and_protect_revenue"
        : "apply_recommendation";
  const trend = demandScore >= 68 ? "up" : demandScore <= 42 ? "down" : "flat";
  const expectedBookings = Math.max(bookings, Math.round((views * (suggestedDiscount ? 0.18 : 0.1)) + activeOffers + importedReservations * 0.18 + manualReservations * 0.12));
  const expectedGuests = Math.max(expectedBookings * 2, Math.round(expectedBookings * numberOr(metrics.average_party_size, 2.4)));
  const revenueWithoutDiscount = Math.round(expectedBookings * reservationValueEstimate);
  const revenueWithDiscount = Math.round(expectedBookings * reservationValueEstimate * (1 - suggestedDiscount / 100) * (suggestedDiscount ? 1.18 : 1));
  const revenueLift = Math.max(0, revenueWithDiscount - revenueWithoutDiscount);
  const weeklyRevenueOpportunity = Math.max(revenueLift, Math.round((100 - demandScore) * 18 + activeOffers * 80));
  const confidenceScore = Math.min(92, Math.max(44, 48 + bookings * 7 + activeOffers * 6 + Math.min(18, views) + Math.min(10, importedReservations + manualReservations)));
  const aiScore = Math.min(100, Math.max(0, Math.round(demandScore * 0.55 + confidenceScore * 0.25 + Math.min(100, activeOffers * 18 + bookings * 9) * 0.2)));
  const riskLevel = demandScore < 40 ? "High" : demandScore < 62 ? "Medium" : "Low";
  const reasons = [
    views < 6 ? "Low view volume" : "Reservation history",
    activeOffers > 0 ? "Offer conversion" : "No active offer coverage",
    "Day of week",
    "Time of day",
    "Weather impact",
    "Local event nearby",
    "Competition level",
    "Traffic condition"
  ];
  const missingData = [];
  if (!metrics.weather_connected) missingData.push("Live weather feed");
  if (!metrics.events_connected) missingData.push("Local events feed");
  if (!metrics.reservation_integration_connected) missingData.push("Reservation platform import");

  return {
    restaurant_id: restaurant?.id || metrics.restaurant_id || null,
    restaurant_name: restaurant?.name || metrics.restaurant_name || "Restaurant",
    demand_score: demandScore,
    ai_score: aiScore,
    revenue_opportunity_weekly: weeklyRevenueOpportunity,
    risk_level: riskLevel,
    suggested_action: suggestedAction,
    suggested_discount_percent: suggestedDiscount,
    confidence: "Directional",
    confidence_score: confidenceScore,
    trend,
    expected_bookings: expectedBookings,
    expected_guests: expectedGuests,
    expected_revenue_without_discount: revenueWithoutDiscount,
    expected_revenue_with_suggested_discount: revenueWithDiscount,
    estimated_revenue_lift: revenueLift,
    ai_recommendation: suggestedAction === "hold_current_strategy"
      ? "Hold current strategy and keep monitoring conversion."
      : suggestedAction === "create_suggested_offer"
        ? `Create a ${suggestedDiscount}% offer for the next low-demand window.`
        : suggestedAction === "reduce_discount_and_protect_revenue"
          ? "Demand is strong. Reduce discounts and protect margin."
          : `Apply a ${suggestedDiscount}% SmartTable recommendation.`,
    reasons,
    inputs: {
      reservations: bookings,
      imported_reservations: importedReservations,
      manual_reservations: manualReservations,
      active_offers: activeOffers,
      views,
      accepted,
      reservation_value_estimate: reservationValueEstimate
    },
    data_status: featureStatusFor("ai_demand_recommendations"),
    model_version: "rules-v1",
    data_used: [
      "restaurant_profile",
      "active_offers",
      "reservation_leads",
      importedReservations ? "imported_reservation_history" : "",
      manualReservations ? "manual_performance_uploads" : "",
      "restaurant_views",
      "accepted_reservations",
      "discount_guardrails"
    ].filter(Boolean),
    missing_data: missingData,
    requires_approval: true,
    autonomous_execution: false
  };
}

function aiExplanationFromForecast(forecast = {}) {
  return {
    what_happened: forecast.demand_score < 45
      ? "Demand is pacing below target for an upcoming service window."
      : forecast.demand_score > 78
        ? "Demand is strong enough to protect margin."
        : "Demand is moderate and should be monitored with a controlled action.",
    why_recommended: forecast.ai_recommendation || "SmartTable recommends a controlled revenue action.",
    data_used: forecast.data_used || [],
    expected_result: {
      expected_bookings: forecast.expected_bookings || 0,
      expected_revenue_lift: forecast.estimated_revenue_lift || 0
    },
    confidence: forecast.confidence_score || 0,
    missing_data: forecast.missing_data || []
  };
}

function aiRecommendationFromForecast(restaurant, forecast = {}, profile = null) {
  const recommendation = {
    id: crypto.randomUUID(),
    restaurant_id: restaurant.id,
    recommendation_type: "demand_recovery",
    status: "pending_approval",
    demand_score: forecast.demand_score,
    recommended_discount: forecast.suggested_discount_percent,
    recommended_start_time: "17:30",
    recommended_end_time: "19:00",
    recommended_date: tomorrowIsoDate(),
    recommended_action: forecast.suggested_action || "apply_recommendation",
    marketing_action: forecast.suggested_action === "reduce_discount_and_protect_revenue" ? "protect_margin" : "notify_favorite_guests",
    expected_bookings: forecast.expected_bookings || 0,
    expected_revenue_lift: forecast.estimated_revenue_lift || 0,
    confidence_score: forecast.confidence_score || 0,
    explanation: aiExplanationFromForecast(forecast),
    data_used: {
      fields: forecast.data_used || [],
      inputs: forecast.inputs || {}
    },
    missing_data: forecast.missing_data || [],
    model_version: forecast.model_version || "rules-v1",
    source: supabaseConfigured ? "smarttable_rules_live_data" : "smarttable_rules_demo_seed",
    created_by: profile?.id || null,
    created_at: nowIso(),
    updated_at: nowIso()
  };
  return recommendation;
}

function reservationOverviewRows() {
  ensureDemo();
  return demo.reservations.map((reservation) => {
    const offer = demo.offers.find((item) => item.id === reservation.offer_id);
    const restaurant = demo.restaurants.find((item) => item.id === reservation.restaurant_id);
    return decorateReservationRow({
      reservation_id: reservation.id,
      reference: reservation.reference,
      restaurant_id: reservation.restaurant_id,
      restaurant_name: restaurant?.name || "Restaurant",
      restaurant_email: restaurantNotificationEmail(restaurant),
      restaurant_phone: restaurant?.phone || "",
      restaurant_address: restaurant?.address || "",
      restaurant_cuisine: restaurant?.cuisine_type || restaurant?.cuisine || "",
      restaurant_neighborhood: restaurant?.district || restaurant?.neighborhood || "",
      restaurant_status: restaurant?.status || "",
      offer_id: reservation.offer_id,
      offer_title: localizedField(offer, "title", "en") || (normalizeReservationType(reservation.reservation_type, reservation.offer_id) === "standard" ? standardReservationLabel("en") : ""),
      offer_date: reservation.reservation_date || offer?.offer_date || reservation.created_at.slice(0, 10),
      offer_time: reservation.reservation_time || offer?.start_time || offer?.offer_time || "",
      reservation_date: reservation.reservation_date || offer?.offer_date || reservation.created_at.slice(0, 10),
      reservation_time: reservation.reservation_time || offer?.start_time || offer?.offer_time || "",
      discount_type: offer?.discount_type || "percent",
      discount_value: numberOr(offer?.discount_value, offer?.discount_percent || reservation.discount_percent || 0),
      discount_percent: numberOr(offer?.discount_percent, offer?.discount_value || reservation.discount_percent || 0),
      party_size: reservation.party_size,
      guest_id: reservation.guest_id,
      guest_name: reservation.guest_name,
      guest_email: reservation.guest_email,
      guest_phone: reservation.guest_phone,
      guest_language: reservation.guest_language || "en",
      restaurant_language: restaurant?.preferred_language || "en",
      notes: reservation.notes,
      partner_notes: reservation.partner_notes || "",
      confirmation_details: reservation.partner_notes || "",
      reservation_type: normalizeReservationType(reservation.reservation_type, reservation.offer_id),
      accepted_at: reservation.accepted_at || null,
      rejected_at: reservation.rejected_at || null,
      cancelled_at: reservation.cancelled_at || null,
      completed_at: reservation.completed_at || null,
      no_show_at: reservation.no_show_at || null,
      arrival_status: reservation.arrival_status || "not_requested",
      arrived_at: reservation.arrived_at || null,
      arrival_source: reservation.arrival_source || null,
      visit_status: reservation.visit_status || "scheduled",
      visit_started_at: reservation.visit_started_at || null,
      visit_completed_at: reservation.visit_completed_at || null,
      completion_source: reservation.completion_source || null,
      expected_visit_duration_minutes: reservation.expected_visit_duration_minutes || null,
      review_eligible_at: reservation.review_eligible_at || null,
      review_invitation_sent_at: reservation.review_invitation_sent_at || null,
      review_submitted_at: reservation.review_submitted_at || null,
      verified_visit: Boolean(reservation.verified_visit),
      post_visit_workflow_version: reservation.post_visit_workflow_version || "",
      status_changed_at: reservation.status_changed_at || null,
      status_changed_by: reservation.status_changed_by || null,
      cancelled_by_label: reservation.cancelled_by_label || "",
      feedback_submitted: demo.consumptionUploads.some((item) => item.reservation_id === reservation.id)
        || demo.restaurantReviews.some((item) => item.reservation_id === reservation.id),
      verified_review_submitted: demo.restaurantReviews.some((item) => item.reservation_id === reservation.id && item.verified_visit),
      source: reservation.source || "smarttable",
      booking_source: reservation.booking_source || "SMARTTABLE",
      booking_status: reservation.booking_status || bookingStatusFromReservationStatus(reservation.status),
      is_test_reservation: Boolean(reservation.is_test_reservation || reservation.test_record || restaurant?.is_test_restaurant || offer?.is_test_offer),
      test_record: Boolean(reservation.test_record || reservation.is_test_reservation || restaurant?.is_test_restaurant || offer?.is_test_offer),
      status: reservation.status,
      created_at: reservation.created_at,
      updated_at: reservation.updated_at
    });
  });
}

function emailLogMetadata(result = {}, context = {}) {
  const {
    recipient_email,
    recipientEmail,
    guest_phone,
    phone,
    ...safeContext
  } = context || {};
  return {
    ...safeContext,
    recipient_hash: recipient_email || recipientEmail ? hashEmailValue(lower(recipient_email || recipientEmail)).slice(0, 16) : null,
    accepted: Boolean(result.accepted),
    status: result.status || "failed",
    error_code: result.errorCode || null,
    error_message: result.errorMessage || null,
    provider_response: result.providerResponse || null
  };
}

function hashEmailValue(value) {
  return crypto.createHash("sha256").update(clean(value)).digest("hex");
}

function maskEmailAddress(email) {
  const value = clean(email).toLowerCase();
  const [local, domain] = value.split("@");
  if (!local || !domain) return value ? "invalid-email" : "";
  const visible = local.length <= 2 ? `${local[0] || "*"}*` : `${local.slice(0, 2)}***${local.slice(-1)}`;
  return `${visible}@${domain}`;
}

function maskEmailLogForAdmin(row = {}) {
  const recipient = row.recipient_email || row.recipient;
  const masked = maskEmailAddress(recipient);
  return {
    ...row,
    log_id: row.log_id || row.id || null,
    queue_id: row.queue_id || null,
    template: row.template || row.email_type || row.event_type || "",
    language: row.language || row.locale || "",
    related_reservation_reference: row.related_reservation_reference || row.reservation_reference || row.reference || "",
    last_safe_error: row.last_safe_error || row.last_error_message || row.error_message || "",
    recipient: masked,
    recipient_email: masked,
    masked_recipient: masked,
    recipient_hash: recipient ? hashEmailValue(lower(recipient)).slice(0, 16) : "",
    metadata: {
      ...(row.metadata || {}),
      recipient_masked: masked
    }
  };
}

function maskEmailQueueForAdmin(row = {}) {
  const recipient = row.recipient_email || row.payload?.to;
  const masked = maskEmailAddress(recipient);
  const status = normalizeEmailQueueStatus(row.status);
  const payloadRedacted = Boolean(row.payload?.redacted);
  const terminal = ["sent", "delivered", "bounced", "failed", "complained", "cancelled"].includes(status);
  const retryAllowed = ["pending", "queued", "failed"].includes(status) && !payloadRedacted && !terminal;
  return {
    ...row,
    queue_id: row.queue_id || row.id || null,
    log_id: row.log_id || row.email_log_id || null,
    template: row.template || row.email_type || row.event_type || "",
    language: row.language || row.locale || "",
    related_reservation_reference: row.related_reservation_reference || row.reservation_reference || row.reference || "",
    last_safe_error: row.last_safe_error || row.last_error_message || "",
    recipient_email: masked,
    masked_recipient: masked,
    retry_allowed: retryAllowed,
    retry_action: retryAllowed
      ? {
        method: "POST",
        endpoint: "/api/admin/email-queue",
        body: { action: "retry", id: row.id }
      }
      : null,
    retry_not_allowed_reason: retryAllowed
      ? null
      : terminal
        ? `Email queue status is ${status}.`
        : payloadRedacted
          ? "Email payload is redacted and cannot be retried without rebuilding the secure message."
          : "Email is not currently retryable.",
    payload: row.payload
      ? {
        subject: row.payload.subject || "",
        redacted: true,
        redaction_reason: row.payload.redaction_reason || "admin_display_masked"
      }
      : null,
    recipient_hash: recipient ? hashEmailValue(lower(recipient)).slice(0, 16) : ""
  };
}

const EMAIL_DIAGNOSTIC_STATUSES = new Set(["pending", "queued", "sending", "sent", "delayed", "delivered", "failed", "bounced", "complained", "cancelled"]);

function emailDiagnosticStatus(row = {}) {
  return normalizeEmailQueueStatus(row.status || row.delivery_status || row.delivery || "pending");
}

function emailDiagnosticType(row = {}) {
  return clean(row.email_type || row.event_type || row.metadata?.email_type || row.metadata?.event_type || "");
}

function emailDiagnosticRecipientType(row = {}) {
  const type = lower(emailDiagnosticType(row));
  if (type.includes("restaurant") || type === "restaurant_request_notice") return "restaurant";
  if (type.includes("admin")) return "admin";
  if (type.includes("guest") || type.includes("reservation") || type.includes("booking") || type.includes("welcome") || type.includes("verification") || type.includes("password")) return "guest";
  if (row.restaurant_id && !row.guest_id && !row.recipient_user_id) return "restaurant";
  if (row.guest_id) return "guest";
  if (row.recipient_user_id) return "user";
  return "unknown";
}

function parseEmailDiagnosticFilters(query = new URLSearchParams()) {
  const statuses = new Set();
  const statusValue = clean(query.get("status") || query.get("delivery_status") || query.get("queue_status"));
  if (statusValue) {
    for (const value of statusValue.split(",")) {
      const status = lower(value.trim());
      if (EMAIL_DIAGNOSTIC_STATUSES.has(status)) statuses.add(status);
    }
  }
  for (const status of ["queued", "sending", "sent", "delayed", "delivered", "failed", "bounced", "complained"]) {
    if (boolValue(query.get(status))) statuses.add(status);
  }
  const rawLimit = clean(query.get("limit"));
  const limit = Math.min(Math.max(1, Math.trunc(rawLimit ? numberOr(rawLimit, 50) : 50)), 250);
  return {
    email_type: clean(query.get("email_type") || query.get("type")),
    recipient_type: lower(query.get("recipient_type") || query.get("recipientType")),
    user: lower(query.get("user") || query.get("user_id") || query.get("recipient_user_id") || query.get("guest_id")),
    restaurant: clean(query.get("restaurant") || query.get("restaurant_id")),
    reservation: clean(query.get("reservation") || query.get("reservation_id") || query.get("reservation_reference") || query.get("reference")),
    statuses: [...statuses],
    limit
  };
}

function emailDiagnosticRowMatches(row = {}, filters = {}) {
  if (filters.email_type && lower(emailDiagnosticType(row)) !== lower(filters.email_type)) return false;
  if (filters.recipient_type && emailDiagnosticRecipientType(row) !== filters.recipient_type) return false;
  if (filters.statuses?.length) {
    const status = emailDiagnosticStatus(row);
    const statusMatched = filters.statuses.some((filterStatus) => filterStatus === status || (filterStatus === "queued" && status === "pending"));
    if (!statusMatched) return false;
  }
  if (filters.restaurant && clean(row.restaurant_id) !== filters.restaurant) return false;
  if (filters.reservation) {
    const reservationValues = [
      row.reservation_id,
      row.related_reservation_reference,
      row.reservation_reference,
      row.reference
    ].map(clean);
    if (!reservationValues.includes(filters.reservation)) return false;
  }
  if (filters.user) {
    const userValues = [
      row.recipient_user_id,
      row.user_id,
      row.guest_id,
      row.recipient_email,
      row.recipient,
      row.metadata?.recipient_email,
      row.metadata?.guest_email
    ].map((value) => lower(value));
    if (!userValues.includes(filters.user)) return false;
  }
  return true;
}

function headerValue(headers = {}, name = "") {
  const lowerName = lower(name);
  const match = Object.entries(headers || {}).find(([key]) => lower(key) === lowerName);
  const value = match?.[1];
  return Array.isArray(value) ? clean(value[0]) : clean(value);
}

function clientIpAddress(headers = {}) {
  const forwarded = headerValue(headers, "x-forwarded-for").split(",")[0];
  return clean(forwarded || headerValue(headers, "x-real-ip") || headerValue(headers, "cf-connecting-ip") || "local").slice(0, 80);
}

function requestIdFromHeaders(headers = {}) {
  return clean(
    headerValue(headers, "x-request-id")
    || headerValue(headers, "x-vercel-id")
    || headerValue(headers, "cf-ray")
    || crypto.randomUUID()
  ).slice(0, 120);
}

function isReadOnlyImpersonationToken(headers = {}) {
  const token = authToken(headers);
  if (!token.startsWith("impersonate.")) return false;
  const profile = profileFromSignedToken(token, "impersonate");
  return clean(profile?.impersonation?.mode || profile?.impersonation_mode || "read") !== "write";
}

function readOnlyImpersonationError(method = "GET", pathname = "") {
  const error = new Error("View-as mode is read-only. Confirm write mode before making changes.");
  error.status = 403;
  error.code = "IMPERSONATION_READ_ONLY";
  error.details = { method, pathname };
  return error;
}

function maskedIpAddress(value = "") {
  const ip = clean(value);
  if (!ip || ip === "local") return ip || "unknown";
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(ip)) {
    const parts = ip.split(".");
    return `${parts[0]}.${parts[1]}.${parts[2]}.*`;
  }
  if (ip.includes(":")) {
    const parts = ip.split(":").filter(Boolean);
    return `${parts.slice(0, 3).join(":") || "ipv6"}::`;
  }
  return "masked";
}

function summarizeUserAgent(value = "") {
  const ua = clean(value).slice(0, 240);
  if (!ua) return "Unknown browser";
  const browser = /Edg\//.test(ua) ? "Edge"
    : /Firefox\//.test(ua) ? "Firefox"
      : /Chrome\//.test(ua) ? "Chrome"
        : /Safari\//.test(ua) ? "Safari"
          : "Browser";
  const platform = /Windows/i.test(ua) ? "Windows"
    : /iPhone|iPad|iPod/i.test(ua) ? "iOS"
      : /Android/i.test(ua) ? "Android"
        : /Mac OS X|Macintosh/i.test(ua) ? "macOS"
          : /Linux/i.test(ua) ? "Linux"
            : "Unknown device";
  return `${browser} on ${platform}`;
}

function localeForLanguage(lang = "en") {
  const language = normalizeLanguage(lang);
  if (language === "hu") return "hu-HU";
  if (language === "es") return "es-ES";
  return "en-US";
}

function localizedSecurityDateTime(date = new Date(), lang = "en") {
  try {
    return new Intl.DateTimeFormat(localeForLanguage(lang), {
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZoneName: "short",
      timeZone: "America/New_York"
    }).format(date);
  } catch {
    return date.toISOString();
  }
}

function allowedOriginHosts(headers = {}) {
  const hosts = new Set();
  const add = (value = "") => {
    try {
      const url = new URL(value);
      if (url.hostname) hosts.add(url.hostname.toLowerCase());
    } catch {
      // Ignore malformed configuration values.
    }
  };
  add(PUBLIC_BASE_URL);
  if (PUBLIC_BASE_URL.includes("smarttablenyc.com")) {
    add("https://www.smarttablenyc.com");
    add("https://smarttablenyc.com");
  }
  if (!IS_PRODUCTION_RUNTIME) {
    const requestHost = lower(headerValue(headers, "host")).replace(/:\d+$/, "");
    if (requestHost) hosts.add(requestHost);
    hosts.add("localhost");
    hosts.add("127.0.0.1");
    hosts.add("::1");
  }
  return hosts;
}

function requestOriginHost(value = "") {
  try {
    const parsed = new URL(value);
    return parsed.hostname.toLowerCase();
  } catch {
    return "";
  }
}

function csrfOriginError(method, pathname, headers = {}) {
  if (["GET", "HEAD", "OPTIONS"].includes(method)) return null;
  if (pathname === "/webhooks/resend") return null;
  if (pathname === "/webhooks/stripe") return null;
  if (pathname === "/webhooks/sms/twilio") return null;
  if (pathname === "/webhooks/voice/twilio") return null;
  const origin = headerValue(headers, "origin");
  const referer = headerValue(headers, "referer");
  const presented = origin || referer;
  if (!presented) return null;
  const host = requestOriginHost(presented);
  if (!host || !allowedOriginHosts(headers).has(host)) {
    return {
      error: "Request origin is not allowed.",
      code: "CSRF_ORIGIN_FORBIDDEN"
    };
  }
  return null;
}

function rateLimitKey(method, pathname, headers = {}) {
  const ip = clientIpAddress(headers);
  const bucket = pathname.startsWith("/auth/") ? "auth" : "api";
  return `${bucket}:${method}:${pathname}:${ip}`;
}

function mutationRateLimitPolicy(pathname = "") {
  if (pathname === "/auth/login") return { limit: AUTH_LOGIN_RATE_LIMIT, windowMs: AUTH_LOGIN_RATE_LIMIT_WINDOW_MS };
  if (pathname === "/auth/signup-guest") return { limit: AUTH_SIGNUP_RATE_LIMIT, windowMs: AUTH_SIGNUP_RATE_LIMIT_WINDOW_MS };
  if (["/auth/forgot-password", "/auth/resend-verification", "/auth/verification"].includes(pathname)) {
    return { limit: AUTH_RECOVERY_RATE_LIMIT, windowMs: AUTH_RECOVERY_RATE_LIMIT_WINDOW_MS };
  }
  if (pathname === "/reservations") return { limit: RESERVATION_CREATE_RATE_LIMIT, windowMs: RESERVATION_CREATE_RATE_LIMIT_WINDOW_MS };
  return {
    limit: pathname.startsWith("/auth/") ? AUTH_MUTATION_RATE_LIMIT : API_MUTATION_RATE_LIMIT,
    windowMs: API_RATE_LIMIT_WINDOW_MS
  };
}

function mutationRateLimitSkipped(method, pathname) {
  if (["GET", "HEAD", "OPTIONS"].includes(method)) return null;
  if (pathname === "/webhooks/resend") return null;
  if (pathname === "/webhooks/stripe") return null;
  if (pathname === "/webhooks/sms/twilio") return null;
  if (pathname === "/webhooks/voice/twilio") return null;
  // Recovery routes preserve enumeration-safe and route-specific responses.
  // They use persistentSensitiveRateLimit inside their handlers instead of
  // the generic mutation limiter so those response contracts remain stable.
  if (["/auth/forgot-password", "/auth/resend-verification", "/auth/verification"].includes(pathname)) return null;
  return false;
}

function localMutationRateLimit(method, pathname, headers = {}) {
  const now = Date.now();
  const key = rateLimitKey(method, pathname, headers);
  const { limit, windowMs } = mutationRateLimitPolicy(pathname);
  const windowStart = now - windowMs;
  const attempts = (apiRateLimitBuckets.get(key) || []).filter((timestamp) => timestamp > windowStart);
  if (attempts.length >= limit) {
    const retryAfterSeconds = Math.max(1, Math.ceil((attempts[0] + windowMs - now) / 1000));
    apiRateLimitBuckets.set(key, attempts);
    return {
      retryAfterSeconds,
      error: "Too many requests. Please wait before trying again.",
      code: "RATE_LIMITED"
    };
  }
  attempts.push(now);
  apiRateLimitBuckets.set(key, attempts);
  if (apiRateLimitBuckets.size > 5000) {
    const retentionWindowMs = Math.max(
      API_RATE_LIMIT_WINDOW_MS,
      AUTH_LOGIN_RATE_LIMIT_WINDOW_MS,
      AUTH_SIGNUP_RATE_LIMIT_WINDOW_MS,
      AUTH_RECOVERY_RATE_LIMIT_WINDOW_MS,
      RESERVATION_CREATE_RATE_LIMIT_WINDOW_MS
    );
    for (const [bucketKey, timestamps] of apiRateLimitBuckets.entries()) {
      const fresh = timestamps.filter((timestamp) => timestamp > now - retentionWindowMs);
      if (fresh.length) apiRateLimitBuckets.set(bucketKey, fresh);
      else apiRateLimitBuckets.delete(bucketKey);
    }
  }
  return null;
}

function distributedRateLimitBucket(method, pathname, headers = {}) {
  return crypto.createHash("sha256")
    .update(rateLimitKey(method, pathname, headers), "utf8")
    .digest("hex");
}

async function distributedMutationRateLimit(method, pathname, headers = {}) {
  const { limit, windowMs } = mutationRateLimitPolicy(pathname);
  const rows = await supabaseFetch("/rest/v1/rpc/consume_api_rate_limit", {
    method: "POST",
    service: true,
    timeoutMs: DISTRIBUTED_RATE_LIMIT_TIMEOUT_MS,
    body: {
      p_bucket_key_hash: distributedRateLimitBucket(method, pathname, headers),
      p_category: pathname.startsWith("/auth/") ? "auth_mutation" : "api_mutation",
      p_limit: limit,
      p_window_seconds: Math.max(1, Math.ceil(windowMs / 1000))
    }
  });
  const result = Array.isArray(rows) ? rows[0] : rows;
  if (!result || typeof result.allowed !== "boolean") {
    throw Object.assign(new Error("Distributed rate limiter returned an invalid response."), {
      status: 502,
      code: "RATE_LIMIT_RESPONSE_INVALID"
    });
  }
  if (result.allowed) return null;
  return {
    status: 429,
    retryAfterSeconds: Math.max(1, Number(result.retry_after_seconds || 1)),
    error: "Too many requests. Please wait before trying again.",
    code: "RATE_LIMITED"
  };
}

async function mutationRateLimit(method, pathname, headers = {}) {
  if (mutationRateLimitSkipped(method, pathname) !== false) return null;
  if (!DISTRIBUTED_RATE_LIMIT_ENABLED) return localMutationRateLimit(method, pathname, headers);

  if (!supabaseConfigured) {
    if (!DISTRIBUTED_RATE_LIMIT_FAIL_CLOSED) return localMutationRateLimit(method, pathname, headers);
    return {
      status: 503,
      retryAfterSeconds: 30,
      error: "Service temporarily unavailable. Please try again.",
      code: "RATE_LIMIT_UNAVAILABLE"
    };
  }

  try {
    return await distributedMutationRateLimit(method, pathname, headers);
  } catch (error) {
    console.error("Distributed rate limiter is unavailable.", {
      code: clean(error?.code || "RATE_LIMIT_UPSTREAM_FAILURE"),
      status: Number(error?.status || 502),
      environment: RUNTIME_ENVIRONMENT
    });
    if (!DISTRIBUTED_RATE_LIMIT_FAIL_CLOSED) return localMutationRateLimit(method, pathname, headers);
    return {
      status: 503,
      retryAfterSeconds: 30,
      error: "Service temporarily unavailable. Please try again.",
      code: "RATE_LIMIT_UNAVAILABLE"
    };
  }
}

function scopedRateLimit(bucketMap, key = "", options = {}) {
  const bucketKey = clean(key);
  if (!bucketKey) return null;
  const now = Date.now();
  const limit = Math.max(1, Number(options.limit || 1));
  const windowMs = Math.max(1000, Number(options.windowMs || 60_000));
  const windowStart = now - windowMs;
  const attempts = (bucketMap.get(bucketKey) || []).filter((timestamp) => timestamp > windowStart);
  if (attempts.length >= limit) {
    const retryAfterSeconds = Math.max(1, Math.ceil((attempts[0] + windowMs - now) / 1000));
    bucketMap.set(bucketKey, attempts);
    return {
      retryAfterSeconds,
      error: clean(options.error || "Too many reservation alert attempts. Please wait before trying again."),
      code: clean(options.code || "RESERVATION_ALERT_RATE_LIMITED")
    };
  }
  attempts.push(now);
  bucketMap.set(bucketKey, attempts);
  if (bucketMap.size > 5000) {
    for (const [bucket, timestamps] of bucketMap.entries()) {
      const fresh = timestamps.filter((timestamp) => timestamp > windowStart);
      if (fresh.length) bucketMap.set(bucket, fresh);
      else bucketMap.delete(bucket);
    }
  }
  return null;
}

function requestPayloadTooLarge(body = {}) {
  const raw = typeof body === "string" ? body : body?.__rawBody;
  if (!raw) return false;
  return Buffer.byteLength(String(raw), "utf8") > MAX_JSON_BODY_BYTES;
}

function rawWebhookBody(body = {}) {
  if (typeof body === "string") return body;
  if (body?.__rawBody) return String(body.__rawBody);
  const clone = { ...(body || {}) };
  delete clone.__rawBody;
  return JSON.stringify(clone);
}

function safeEqualString(a = "", b = "") {
  const left = Buffer.from(clean(a));
  const right = Buffer.from(clean(b));
  if (left.length !== right.length) return false;
  return crypto.timingSafeEqual(left, right);
}

function resendWebhookSecretBytes(secret = "") {
  const value = clean(secret);
  if (!value) return null;
  const encoded = value.startsWith("whsec_") ? value.slice(6) : value;
  try {
    return Buffer.from(encoded, "base64");
  } catch {
    return Buffer.from(value);
  }
}

function verifyResendWebhookSignature(headers = {}, body = {}) {
  if (!RESEND_WEBHOOK_SECRET) return { ok: false, reason: "RESEND_WEBHOOK_SECRET_NOT_CONFIGURED" };
  const raw = rawWebhookBody(body);
  const svixId = headerValue(headers, "svix-id");
  const svixTimestamp = headerValue(headers, "svix-timestamp");
  const svixSignature = headerValue(headers, "svix-signature");
  const nowSeconds = Math.floor(Date.now() / 1000);
  if (svixId && svixTimestamp && svixSignature) {
    const timestamp = Number(svixTimestamp);
    if (!Number.isFinite(timestamp) || Math.abs(nowSeconds - timestamp) > EMAIL_WEBHOOK_TOLERANCE_SECONDS) {
      return { ok: false, reason: "WEBHOOK_TIMESTAMP_OUTSIDE_TOLERANCE" };
    }
    const secretBytes = resendWebhookSecretBytes(RESEND_WEBHOOK_SECRET);
    const signedContent = `${svixId}.${svixTimestamp}.${raw}`;
    const expected = crypto.createHmac("sha256", secretBytes).update(signedContent).digest("base64");
    const received = svixSignature
      .split(/\s+/)
      .map((part) => {
        const pieces = part.split(",").map(clean).filter(Boolean);
        return pieces.length > 1 ? pieces.at(-1) : pieces[0];
      })
      .map(clean)
      .filter(Boolean);
    if (received.some((signature) => safeEqualString(signature, expected))) return { ok: true, scheme: "svix" };
    return { ok: false, reason: "WEBHOOK_SIGNATURE_MISMATCH" };
  }

  if (IS_PRODUCTION_RUNTIME) return { ok: false, reason: "WEBHOOK_SIGNATURE_MISSING" };
  const hmacSignature = headerValue(headers, "x-resend-signature") || headerValue(headers, "x-smarttable-signature");
  if (!hmacSignature) return { ok: false, reason: "WEBHOOK_SIGNATURE_MISSING" };
  const expected = crypto.createHmac("sha256", RESEND_WEBHOOK_SECRET).update(raw).digest("hex");
  const received = hmacSignature.replace(/^sha256=/i, "");
  return safeEqualString(received, expected)
    ? { ok: true, scheme: "hmac-sha256" }
    : { ok: false, reason: "WEBHOOK_SIGNATURE_MISMATCH" };
}

function mapProviderEmailEventStatus(eventType = "", data = {}) {
  const type = lower(eventType);
  const status = lower(data.status || data.delivery_status);
  if (type.includes("delivered") || status === "delivered") return "delivered";
  if (type.includes("bounced") || status === "bounced") return "bounced";
  if (type.includes("complained") || type.includes("complaint") || status === "complained") return "complained";
  if (type.includes("failed") || status === "failed") return "failed";
  if (type.includes("delivery_delayed") || type.includes("delayed") || type.includes("deferred") || status === "delayed" || status === "deferred") return "delayed";
  if (type.includes("sent") || status === "sent") return "sent";
  return "queued";
}

const EMAIL_STATUS_RANK = {
  pending: 0,
  queued: 1,
  sending: 2,
  sent: 3,
  delayed: 4,
  delivered: 5,
  failed: 6,
  bounced: 7,
  complained: 8,
  cancelled: 9
};

function emailStatusRank(status = "") {
  const normalized = clean(status).toLowerCase();
  return EMAIL_STATUS_RANK[normalized] ?? 0;
}

function shouldApplyProviderStatus(previousStatus = "", nextStatus = "") {
  const previous = clean(previousStatus).toLowerCase();
  const next = clean(nextStatus).toLowerCase();
  if (!previous || previous === next) return true;
  if (["bounced", "complained", "failed", "cancelled"].includes(previous) && !["bounced", "complained", "failed"].includes(next)) return false;
  if (previous === "delivered" && ["sent", "queued", "sending", "delayed"].includes(next)) return false;
  return emailStatusRank(next) >= emailStatusRank(previous);
}

function providerEventTimestamp(payload = {}, data = {}) {
  const value = clean(data.created_at || data.timestamp || payload.created_at || payload.timestamp);
  const parsed = value ? new Date(value) : null;
  return parsed && !Number.isNaN(parsed.getTime()) ? parsed.toISOString() : nowIso();
}

function sanitizeProviderEventDetails(data = {}) {
  const raw = data.error || data.reason || data.bounce || data.complaint || data.status || data.delivery_status || null;
  if (!raw) return null;
  if (typeof raw === "string") return clean(raw).slice(0, 300);
  if (typeof raw === "object") {
    return Object.fromEntries(Object.entries(raw)
      .filter(([key]) => !/secret|token|password|authorization|api[_-]?key/i.test(key))
      .slice(0, 12)
      .map(([key, value]) => [key, typeof value === "string" ? clean(value).slice(0, 180) : value]));
  }
  return null;
}

function emailLogPatchForProviderEvent(row = {}, event = {}) {
  const now = nowIso();
  const eventAt = event.event_timestamp || now;
  const nextStatus = shouldApplyProviderStatus(row.status || row.delivery_status, event.status)
    ? event.status
    : clean(row.status || row.delivery_status || "sent");
  const previousEvents = Array.isArray(row.metadata?.provider_events) ? row.metadata.provider_events : [];
  const nextEvents = previousEvents.some((item) => item.event_id === event.event_id)
    ? previousEvents
    : [...previousEvents, {
      event_id: event.event_id,
      event_type: event.event_type,
      status: event.status,
      event_timestamp: eventAt,
      provider_message_id: event.provider_message_id,
      sanitized_error: event.sanitized_error || null,
      received_at: now
    }].slice(-20);
  return {
    delivery_status: nextStatus,
    status: nextStatus,
    delivered_at: nextStatus === "delivered" ? (row.delivered_at || eventAt) : row.delivered_at || null,
    failed_at: ["failed", "bounced", "complained"].includes(nextStatus) ? (row.failed_at || eventAt) : row.failed_at || null,
    last_error_code: ["failed", "bounced", "complained"].includes(nextStatus) ? clean(event.event_type).toUpperCase().replace(/[^A-Z0-9_]+/g, "_") : row.last_error_code || null,
    last_error_message: ["failed", "bounced", "complained"].includes(nextStatus) && event.sanitized_error ? JSON.stringify(event.sanitized_error).slice(0, 500) : row.last_error_message || null,
    error_message: ["failed", "bounced", "complained"].includes(nextStatus) && event.sanitized_error ? JSON.stringify(event.sanitized_error).slice(0, 500) : row.error_message || null,
    updated_at: now,
    metadata: {
      ...(row.metadata || {}),
      provider_events: nextEvents,
      last_provider_event_type: event.event_type,
      last_provider_event_status: event.status,
      last_provider_event_at: eventAt,
      last_webhook_received_at: now,
      last_provider_error: event.sanitized_error || null
    }
  };
}

async function updateEmailLogFromProviderEvent(event = {}) {
  if (!event.provider_message_id) return { updated: false, reason: "MISSING_PROVIDER_MESSAGE_ID" };
  if (!supabaseConfigured) {
    ensureDemo();
    const row = demo.emailLogs.find((item) => item.provider_message_id === event.provider_message_id || item.provider_id === event.provider_message_id);
    if (!row) return { updated: false, reason: "EMAIL_LOG_NOT_FOUND" };
    const events = Array.isArray(row.metadata?.provider_events) ? row.metadata.provider_events : [];
    if (event.event_id && events.some((item) => item.event_id === event.event_id)) return { updated: false, reason: "WEBHOOK_EVENT_ALREADY_PROCESSED" };
    Object.assign(row, emailLogPatchForProviderEvent(row, event));
    return { updated: true, email_log_id: row.id, status: row.status };
  }
  const rows = await supabaseFetch(`/rest/v1/email_logs?select=*&or=(provider_message_id.eq.${encodeURIComponent(event.provider_message_id)},provider_id.eq.${encodeURIComponent(event.provider_message_id)})&limit=1`, { service: true }).catch(() => []);
  const row = rows?.[0];
  if (!row) return { updated: false, reason: "EMAIL_LOG_NOT_FOUND" };
  const events = Array.isArray(row.metadata?.provider_events) ? row.metadata.provider_events : [];
  if (event.event_id && events.some((item) => item.event_id === event.event_id)) return { updated: false, reason: "WEBHOOK_EVENT_ALREADY_PROCESSED" };
  await supabaseFetch(`/rest/v1/email_logs?id=eq.${encodeURIComponent(row.id)}`, {
    method: "PATCH",
    service: true,
    headers: { Prefer: "return=minimal" },
    body: await filterSupabaseTablePayload("email_logs", emailLogPatchForProviderEvent(row, event))
  });
  return { updated: true, email_log_id: row.id, status: event.status };
}

function normalizeEmailDeliveryStatus(result = {}) {
  const status = clean(result.delivery_status || result.status || result.delivery).toLowerCase();
  if (["pending", "queued", "sending", "sent", "delayed", "delivered", "bounced", "failed", "complained", "cancelled"].includes(status)) return status;
  return isEmailAccepted(result) ? "sent" : "failed";
}

function isTemporaryEmailFailure(errorCode = "") {
  const code = clean(errorCode).toUpperCase();
  return code === "EMAIL_PROVIDER_REQUEST_FAILED" ||
    code === "EMAIL_PROVIDER_TIMEOUT" ||
    /^RESEND_(408|409|425|429|500|502|503|504)$/.test(code);
}

function isPermanentEmailFailure(errorCode = "") {
  const code = clean(errorCode).toUpperCase();
  if (!code) return false;
  if (isTemporaryEmailFailure(code)) return false;
  return code.startsWith("INVALID_") ||
    code.startsWith("MISSING_") ||
    code === "EMAIL_PROVIDER_NOT_CONFIGURED" ||
    code === "EMAIL_PROVIDER_UNSUPPORTED" ||
    code === "EMAIL_FETCH_UNAVAILABLE" ||
    /^RESEND_(400|401|403|404|422)$/.test(code);
}

function emailTypeFromContext(context = {}) {
  return clean(context.email_type || context.emailType || context.event_type || "email");
}

function emailLocaleFromContext(context = {}, message = {}) {
  return normalizeLanguage(context.locale || context.lang || context.language || message.locale || "en");
}

function emailIdempotencyKey(message = {}, context = {}) {
  const explicit = clean(context.idempotency_key || context.idempotencyKey);
  if (explicit) return explicit;
  const emailType = emailTypeFromContext(context);
  const recipient = lower(message.to || context.recipient_email || context.recipientEmail);
  const scope = clean(context.reservation_id || context.reservationId || context.recipient_user_id || context.recipientUserId || context.guest_id || context.restaurant_id || recipient || "global");
  return hashEmailValue(`${emailType}:${scope}:${recipient}`);
}

function normalizeEmailDeliveryContext(message = {}, context = {}) {
  const locale = emailLocaleFromContext(context, message);
  return {
    ...context,
    email_type: emailTypeFromContext(context),
    event_type: clean(context.event_type || context.email_type || context.emailType || "email"),
    recipient_email: lower(message.to || context.recipient_email || context.recipientEmail),
    recipient_user_id: clean(context.recipient_user_id || context.recipientUserId),
    restaurant_id: clean(context.restaurant_id || context.restaurantId),
    reservation_id: clean(context.reservation_id || context.reservationId),
    guest_id: clean(context.guest_id || context.guestId),
    campaign_id: clean(context.campaign_id || context.campaignId),
    message_campaign_id: clean(context.message_campaign_id || context.messageCampaignId),
    locale,
    template_version: clean(context.template_version || context.templateVersion || EMAIL_TEMPLATE_VERSION),
    idempotency_key: emailIdempotencyKey(message, context)
  };
}

function emailLogAttemptCount(row = {}) {
  if (!row) return 0;
  return Math.max(0, Number(row.attempt_count ?? row.attemptCount ?? 0));
}

function emailLogLastErrorCode(row = {}) {
  if (!row) return "";
  return clean(row.last_error_code || row.error_code || row.metadata?.error_code);
}

function emailLogStatus(row = {}) {
  if (!row) return "failed";
  return clean(row.delivery_status || row.status || "failed").toLowerCase();
}

function emailSendDecision(existingLog = null) {
  if (!existingLog) return { shouldSend: true, reason: "new" };
  const status = emailLogStatus(existingLog);
  if (["queued", "sending", "sent", "delayed", "delivered"].includes(status)) {
    return { shouldSend: false, reason: "already_accepted" };
  }
  const errorCode = emailLogLastErrorCode(existingLog);
  if (isPermanentEmailFailure(errorCode)) {
    return { shouldSend: false, reason: "permanent_failure" };
  }
  if (emailLogAttemptCount(existingLog) >= EMAIL_RETRY_LIMIT) {
    return { shouldSend: false, reason: "retry_limit_reached" };
  }
  return { shouldSend: true, reason: "retry_temporary_failure" };
}

function normalizeEmailQueueStatus(value = "") {
  const status = clean(value).toLowerCase();
  return ["pending", "queued", "sending", "sent", "delayed", "delivered", "bounced", "failed", "complained", "cancelled"].includes(status)
    ? status
    : "queued";
}

function emailRetryDelayMs(attemptCount = 0) {
  const index = Math.min(Math.max(0, Number(attemptCount || 0) - 1), EMAIL_QUEUE_RETRY_DELAYS_MS.length - 1);
  return EMAIL_QUEUE_RETRY_DELAYS_MS[index] || EMAIL_QUEUE_RETRY_DELAYS_MS.at(-1) || 60_000;
}

function isSensitiveQueuedEmail(context = {}) {
  const type = clean(context.email_type || context.event_type).toLowerCase();
  return ["email_verification", "password_reset"].includes(type);
}

function emailQueuePayloadForStorage(message = {}, context = {}) {
  const payload = {
    to: lower(message.to),
    from: clean(message.from || EMAIL_FROM),
    subject: clean(message.subject),
    reply_to: clean(message.replyTo || message.reply_to || EMAIL_REPLY_TO),
    redacted: false
  };
  if (isSensitiveQueuedEmail(context)) {
    return {
      ...payload,
      text: "",
      html: "",
      redacted: true,
      redaction_reason: "secure_token_not_persisted"
    };
  }
  return {
    ...payload,
    text: clean(message.text),
    html: clean(message.html)
  };
}

function emailMessageFromQueuePayload(payload = {}) {
  if (!payload || payload.redacted) return null;
  return {
    to: payload.to,
    from: payload.from || EMAIL_FROM,
    reply_to: payload.reply_to || EMAIL_REPLY_TO,
    subject: payload.subject,
    text: payload.text || "",
    html: payload.html || ""
  };
}

function emailQueueRow(message = {}, context = {}, existingLog = null) {
  const now = nowIso();
  return {
    id: crypto.randomUUID(),
    email_log_id: existingLog?.id || null,
    email_type: context.email_type || context.event_type || "email",
    event_type: context.event_type || context.email_type || "email",
    recipient_email: lower(message.to || context.recipient_email),
    recipient_user_id: context.recipient_user_id || null,
    restaurant_id: context.restaurant_id || null,
    reservation_id: context.reservation_id || null,
    campaign_id: context.campaign_id || null,
    message_campaign_id: context.message_campaign_id || null,
    provider: "resend",
    provider_message_id: existingLog?.provider_message_id || existingLog?.provider_id || null,
    status: "queued",
    attempt_count: emailLogAttemptCount(existingLog),
    max_attempts: EMAIL_QUEUE_MAX_ATTEMPTS,
    locale: context.locale || "en",
    template_version: context.template_version || EMAIL_TEMPLATE_VERSION,
    idempotency_key: context.idempotency_key || emailIdempotencyKey(message, context),
    payload: emailQueuePayloadForStorage(message, context),
    next_attempt_at: now,
    last_attempt_at: null,
    sent_at: null,
    delivered_at: null,
    failed_at: null,
    last_error_code: null,
    last_error_message: null,
    created_at: now,
    updated_at: now
  };
}

async function findEmailQueueByIdempotency(idempotencyKey) {
  const key = clean(idempotencyKey);
  if (!key) return null;
  if (!supabaseConfigured) {
    ensureDemo();
    return demo.emailQueue.find((item) => item.idempotency_key === key) || null;
  }
  try {
    const rows = await supabaseFetch(`/rest/v1/email_queue?select=*&idempotency_key=eq.${encodeURIComponent(key)}&limit=1`, { service: true });
    return rows?.[0] || null;
  } catch (error) {
    console.error("[email-queue] Could not read queue record:", error.message);
    return null;
  }
}

async function createEmailQueueRecord(message = {}, context = {}, existingLog = null) {
  const existingQueue = await findEmailQueueByIdempotency(context.idempotency_key);
  if (existingQueue) return existingQueue;
  const row = emailQueueRow(message, context, existingLog);
  if (!supabaseConfigured) {
    ensureDemo();
    demo.emailQueue.unshift(row);
    return row;
  }
  try {
    const rows = await supabaseFetch("/rest/v1/email_queue?select=*", {
      method: "POST",
      service: true,
      headers: { Prefer: "return=representation" },
      body: await filterSupabaseTablePayload("email_queue", row)
    });
    return rows?.[0] || row;
  } catch (error) {
    console.error("[email-queue] Queue write failed; attempting immediate delivery only:", error.message);
    return { ...row, queue_error: error.message, transient: true };
  }
}

async function patchEmailQueueRecord(queueRecord = {}, patch = {}) {
  if (!queueRecord?.id) return null;
  const payload = {
    ...patch,
    status: patch.status ? normalizeEmailQueueStatus(patch.status) : undefined,
    updated_at: nowIso()
  };
  Object.keys(payload).forEach((key) => payload[key] === undefined && delete payload[key]);
  if (!supabaseConfigured || queueRecord.transient) {
    ensureDemo();
    const index = demo.emailQueue.findIndex((item) => item.id === queueRecord.id);
    const next = { ...queueRecord, ...payload };
    if (index >= 0) demo.emailQueue[index] = { ...demo.emailQueue[index], ...payload };
    return next;
  }
  try {
    await supabaseFetch(`/rest/v1/email_queue?id=eq.${encodeURIComponent(queueRecord.id)}`, {
      method: "PATCH",
      service: true,
      headers: { Prefer: "return=minimal" },
      body: await filterSupabaseTablePayload("email_queue", payload)
    });
    return { ...queueRecord, ...payload };
  } catch (error) {
    console.error("[email-queue] Queue update failed:", error.message);
    return { ...queueRecord, ...payload, queue_error: error.message };
  }
}

function emailQueuePatchAfterAttempt(result = {}, logRecord = {}, queueRecord = {}, context = {}) {
  const now = nowIso();
  const status = normalizeEmailDeliveryStatus(result);
  const attemptCount = logRecord?.attempt_count || Number(queueRecord.attempt_count || 0) + 1;
  const accepted = isEmailAccepted(result);
  const sensitive = isSensitiveQueuedEmail(context);
  const canRetry = !accepted &&
    !sensitive &&
    isTemporaryEmailFailure(result.errorCode) &&
    attemptCount < Number(queueRecord.max_attempts || EMAIL_QUEUE_MAX_ATTEMPTS);
  const terminalStatus = accepted ? "sent" : canRetry ? "queued" : status;
  const nextAttemptAt = canRetry
    ? new Date(Date.now() + emailRetryDelayMs(attemptCount)).toISOString()
    : null;
  return {
    email_log_id: logRecord?.id || queueRecord.email_log_id || null,
    provider_message_id: result.messageId || result.provider_id || queueRecord.provider_message_id || null,
    status: terminalStatus,
    attempt_count: attemptCount,
    last_attempt_at: now,
    next_attempt_at: nextAttemptAt,
    sent_at: accepted ? (queueRecord.sent_at || now) : queueRecord.sent_at || null,
    delivered_at: status === "delivered" ? (queueRecord.delivered_at || now) : queueRecord.delivered_at || null,
    failed_at: ["failed", "bounced", "complained", "cancelled"].includes(terminalStatus) ? now : queueRecord.failed_at || null,
    last_error_code: result.errorCode || null,
    last_error_message: result.errorMessage || null,
    payload: accepted || (!canRetry && !sensitive)
      ? { ...(queueRecord.payload || {}), text: "", html: "", redacted: true, redaction_reason: accepted ? "redacted_after_provider_acceptance" : "redacted_after_terminal_failure" }
      : queueRecord.payload || emailQueuePayloadForStorage({}, context)
  };
}

async function processEmailQueueRecord(queueRecord = {}, message = null, context = {}, existingLog = null) {
  const queuedMessage = message || emailMessageFromQueuePayload(queueRecord.payload);
  const deliveryContext = normalizeEmailDeliveryContext(queuedMessage || { to: queueRecord.recipient_email, subject: queueRecord.payload?.subject || "" }, {
    ...context,
    email_type: queueRecord.email_type,
    event_type: queueRecord.event_type || queueRecord.email_type,
    recipient_user_id: queueRecord.recipient_user_id,
    restaurant_id: queueRecord.restaurant_id,
    reservation_id: queueRecord.reservation_id,
    campaign_id: queueRecord.campaign_id,
    message_campaign_id: queueRecord.message_campaign_id,
    locale: queueRecord.locale,
    template_version: queueRecord.template_version,
    idempotency_key: queueRecord.idempotency_key
  });
  const currentLog = existingLog || await findEmailDeliveryLog(deliveryContext.idempotency_key);
  if (!queuedMessage) {
    const result = {
      to: queueRecord.recipient_email,
      from: EMAIL_FROM,
      subject: queueRecord.payload?.subject || "",
      text: "",
      html: "",
      accepted: false,
      provider: "resend",
      messageId: null,
      provider_id: null,
      status: "failed",
      delivery: "failed",
      errorCode: "EMAIL_QUEUE_PAYLOAD_REDACTED",
      errorMessage: "This queued email cannot be retried because its secure link was not persisted.",
      providerResponse: {},
      created_at: nowIso()
    };
    const logRecord = await recordEmailDelivery(result, deliveryContext, currentLog);
    const nextQueue = await patchEmailQueueRecord(queueRecord, emailQueuePatchAfterAttempt(result, logRecord, queueRecord, deliveryContext));
    return { result, logRecord, queueRecord: nextQueue };
  }
  await patchEmailQueueRecord(queueRecord, {
    status: "sending",
    last_attempt_at: nowIso()
  });
  const result = await emailService.sendEmail(queuedMessage);
  const logRecord = await recordEmailDelivery(result, deliveryContext, currentLog);
  const nextQueue = await patchEmailQueueRecord(queueRecord, emailQueuePatchAfterAttempt(result, logRecord, queueRecord, deliveryContext));
  return { result, logRecord, queueRecord: nextQueue };
}

async function updateEmailQueueFromProviderEvent(event = {}) {
  if (!event.provider_message_id) return { updated: false, reason: "MISSING_PROVIDER_MESSAGE_ID" };
  if (!supabaseConfigured) {
    ensureDemo();
    const row = demo.emailQueue.find((item) => item.provider_message_id === event.provider_message_id);
    if (!row) return { updated: false, reason: "EMAIL_QUEUE_NOT_FOUND" };
    const status = shouldApplyProviderStatus(row.status, event.status) ? event.status : row.status;
    const patch = {
      status,
      delivered_at: status === "delivered" ? (row.delivered_at || event.event_timestamp || nowIso()) : row.delivered_at || null,
      failed_at: ["failed", "bounced", "complained"].includes(status) ? (row.failed_at || event.event_timestamp || nowIso()) : row.failed_at || null,
      last_error_code: ["failed", "bounced", "complained"].includes(status) ? clean(event.event_type).toUpperCase().replace(/[^A-Z0-9_]+/g, "_") : row.last_error_code || null,
      last_error_message: ["failed", "bounced", "complained"].includes(status) && event.sanitized_error ? JSON.stringify(event.sanitized_error).slice(0, 500) : row.last_error_message || null,
      provider_message_id: event.provider_message_id
    };
    Object.assign(row, patch, { updated_at: nowIso() });
    return { updated: true, email_queue_id: row.id, status };
  }
  const rows = await supabaseFetch(`/rest/v1/email_queue?select=*&provider_message_id=eq.${encodeURIComponent(event.provider_message_id)}&limit=1`, { service: true }).catch(() => []);
  const row = rows?.[0];
  if (!row) return { updated: false, reason: "EMAIL_QUEUE_NOT_FOUND" };
  const status = shouldApplyProviderStatus(row.status, event.status) ? event.status : row.status;
  const patch = {
    status,
    delivered_at: status === "delivered" ? (row.delivered_at || event.event_timestamp || nowIso()) : undefined,
    failed_at: ["failed", "bounced", "complained"].includes(status) ? (row.failed_at || event.event_timestamp || nowIso()) : undefined,
    last_error_code: ["failed", "bounced", "complained"].includes(status) ? clean(event.event_type).toUpperCase().replace(/[^A-Z0-9_]+/g, "_") : undefined,
    last_error_message: ["failed", "bounced", "complained"].includes(status) && event.sanitized_error ? JSON.stringify(event.sanitized_error).slice(0, 500) : undefined,
    provider_message_id: event.provider_message_id
  };
  await patchEmailQueueRecord(row, patch);
  return { updated: true, email_queue_id: row.id, status };
}

function resultFromExistingEmailLog(message = {}, context = {}, existingLog = {}, decision = {}) {
  const status = emailLogStatus(existingLog);
  const accepted = ["queued", "sending", "sent", "delayed", "delivered"].includes(status);
  const errorCode = emailLogLastErrorCode(existingLog) || (decision.reason === "retry_limit_reached" ? "EMAIL_RETRY_LIMIT_REACHED" : null);
  const errorMessage = clean(existingLog.last_error_message || existingLog.error_message || existingLog.metadata?.error_message) ||
    (decision.reason === "already_accepted"
      ? "Email was already accepted by the provider for this idempotency key."
      : "Email delivery was not retried for this idempotency key.");
  return {
    to: clean(message.to),
    from: clean(message.from || EMAIL_FROM),
    subject: clean(message.subject || existingLog.subject),
    text: "",
    html: "",
    accepted,
    provider: clean(existingLog.provider || "resend"),
    messageId: clean(existingLog.provider_message_id || existingLog.provider_id),
    provider_id: clean(existingLog.provider_message_id || existingLog.provider_id),
    status,
    delivery: status,
    errorCode,
    errorMessage: accepted ? null : errorMessage,
    providerResponse: {},
    duplicate_suppressed: true,
    suppression_reason: decision.reason,
    created_at: nowIso()
  };
}

async function findEmailDeliveryLog(idempotencyKey) {
  const key = clean(idempotencyKey);
  if (!key) return null;
  if (!supabaseConfigured) {
    ensureDemo();
    return demo.emailLogs.find((item) => item.idempotency_key === key) || null;
  }
  try {
    const rows = await supabaseFetch(`/rest/v1/email_logs?select=*&idempotency_key=eq.${encodeURIComponent(key)}&limit=1`, { service: true });
    return rows?.[0] || null;
  } catch (error) {
    console.error("[email-log] Could not read idempotency log:", error.message);
    return null;
  }
}

function emailLogPayload(result = {}, context = {}, existingLog = null) {
  const now = nowIso();
  const status = normalizeEmailDeliveryStatus(result);
  const attemptCount = emailLogAttemptCount(existingLog) + 1;
  const metadata = emailLogMetadata(result, {
    ...context,
    attempt_count: attemptCount,
    duplicate_suppressed: Boolean(result.duplicate_suppressed),
    suppression_reason: result.suppression_reason || null
  });
  return {
    id: existingLog?.id || crypto.randomUUID(),
    reservation_id: context.reservation_id || null,
    restaurant_id: context.restaurant_id || null,
    guest_id: context.guest_id || null,
    campaign_id: context.campaign_id || null,
    message_campaign_id: context.message_campaign_id || null,
    recipient_user_id: context.recipient_user_id || null,
    email_type: context.email_type || context.event_type || "email",
    event_type: context.event_type || context.email_type || "email",
    recipient: result.to,
    recipient_email: result.to,
    subject: result.subject,
    provider: result.provider || "resend",
    provider_id: result.messageId || result.provider_id || null,
    provider_message_id: result.messageId || result.provider_id || null,
    delivery_status: status,
    status,
    attempt_count: attemptCount,
    last_error_code: result.errorCode || null,
    last_error_message: result.errorMessage || null,
    error_message: result.errorMessage || null,
    sent_at: ["queued", "sent", "delivered"].includes(status) ? (existingLog?.sent_at || now) : existingLog?.sent_at || null,
    delivered_at: status === "delivered" ? (existingLog?.delivered_at || now) : existingLog?.delivered_at || null,
    failed_at: ["failed", "bounced", "complained", "cancelled"].includes(status) ? now : existingLog?.failed_at || null,
    locale: context.locale || "en",
    template_version: context.template_version || EMAIL_TEMPLATE_VERSION,
    idempotency_key: context.idempotency_key || null,
    metadata,
    created_at: existingLog?.created_at || now,
    updated_at: now
  };
}

function legacyEmailEventPayload(result = {}, context = {}) {
  return {
    reservation_id: context.reservation_id || null,
    event_type: context.event_type || "notification",
    recipient: result.to,
    subject: result.subject,
    provider: result.provider || "resend",
    provider_id: result.messageId || result.provider_id || null,
    status: normalizeEmailDeliveryStatus(result)
  };
}

async function recordEmailDelivery(result = {}, context = {}, existingLog = null) {
  const payload = emailLogPayload(result, context, existingLog);
  if (supabaseConfigured) {
    try {
      await supabaseFetch("/rest/v1/email_events", {
      method: "POST",
      service: true,
      headers: { Prefer: "return=minimal" },
      body: await filterSupabaseTablePayload("email_events", legacyEmailEventPayload(result, context))
      });
    } catch (error) {
      console.error("[email-log] Legacy email event write failed:", error.message);
    }
    try {
      if (existingLog?.id) {
        await supabaseFetch(`/rest/v1/email_logs?id=eq.${encodeURIComponent(existingLog.id)}`, {
          method: "PATCH",
          service: true,
          headers: { Prefer: "return=minimal" },
          body: await filterSupabaseTablePayload("email_logs", payload)
        });
      } else {
        await supabaseFetch("/rest/v1/email_logs", {
          method: "POST",
          service: true,
          headers: { Prefer: "return=minimal" },
          body: await filterSupabaseTablePayload("email_logs", payload)
        });
      }
    } catch (error) {
      console.error("[email-log] Delivery log write failed:", error.message);
      return { ...payload, log_error: error.message };
    }
    return payload;
  }

  ensureDemo();
  demo.emailEvents.unshift({
    id: crypto.randomUUID(),
    ...legacyEmailEventPayload(result, context),
    error_code: result.errorCode || null,
    error_message: result.errorMessage || null,
    created_at: nowIso()
  });
  if (existingLog?.id) {
    const index = demo.emailLogs.findIndex((item) => item.id === existingLog.id);
    if (index >= 0) demo.emailLogs[index] = { ...demo.emailLogs[index], ...payload };
  } else {
    demo.emailLogs.unshift(payload);
  }
  return payload;
}

async function sendEmail(message, context = {}) {
  const deliveryContext = normalizeEmailDeliveryContext(message, context);
  const existingLog = await findEmailDeliveryLog(deliveryContext.idempotency_key);
  const decision = emailSendDecision(existingLog);
  if (!decision.shouldSend) {
    const result = resultFromExistingEmailLog(message, deliveryContext, existingLog, decision);
    const logRecord = await recordEmailDelivery(result, deliveryContext, existingLog);
    return {
      ...result,
      event_type: deliveryContext.event_type || "email",
      email_type: deliveryContext.email_type || deliveryContext.event_type || "email",
      reservation_id: deliveryContext.reservation_id || null,
      restaurant_id: deliveryContext.restaurant_id || null,
      recipient_user_id: deliveryContext.recipient_user_id || null,
      locale: deliveryContext.locale,
      template_version: deliveryContext.template_version,
      idempotencyKey: deliveryContext.idempotency_key,
      idempotency_key: deliveryContext.idempotency_key,
      attemptCount: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
      attempt_count: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
      emailLogId: logRecord?.id || existingLog?.id || null,
      emailQueueId: null,
      email_queue_id: null
    };
  }
  const queueRecord = await createEmailQueueRecord(message, deliveryContext, existingLog);
  const processed = await processEmailQueueRecord(queueRecord, message, deliveryContext, existingLog);
  const result = processed.result;
  const logRecord = processed.logRecord;
  return {
    ...result,
    event_type: deliveryContext.event_type || "email",
    email_type: deliveryContext.email_type || deliveryContext.event_type || "email",
    reservation_id: deliveryContext.reservation_id || null,
    restaurant_id: deliveryContext.restaurant_id || null,
    recipient_user_id: deliveryContext.recipient_user_id || null,
    locale: deliveryContext.locale,
    template_version: deliveryContext.template_version,
    idempotencyKey: deliveryContext.idempotency_key,
    idempotency_key: deliveryContext.idempotency_key,
    attemptCount: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
    attempt_count: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
    emailLogId: logRecord?.id || existingLog?.id || null,
    emailQueueId: processed.queueRecord?.id || queueRecord?.id || null,
    email_queue_id: processed.queueRecord?.id || queueRecord?.id || null,
    queue_status: processed.queueRecord?.status || null
  };
}

async function recordEmailConfigurationFailure(message, context = {}, errorCode = "EMAIL_CONFIGURATION_ERROR", errorMessage = "Email could not be queued because required recipient configuration is missing or invalid.") {
  const deliveryContext = normalizeEmailDeliveryContext(message, context);
  const existingLog = await findEmailDeliveryLog(deliveryContext.idempotency_key);
  const decision = emailSendDecision(existingLog);
  if (!decision.shouldSend) {
    const result = resultFromExistingEmailLog(message, deliveryContext, existingLog, decision);
    return {
      ...result,
      event_type: deliveryContext.event_type || "email",
      email_type: deliveryContext.email_type || deliveryContext.event_type || "email",
      reservation_id: deliveryContext.reservation_id || null,
      restaurant_id: deliveryContext.restaurant_id || null,
      recipient_user_id: deliveryContext.recipient_user_id || null,
      locale: deliveryContext.locale,
      template_version: deliveryContext.template_version,
      idempotencyKey: deliveryContext.idempotency_key,
      idempotency_key: deliveryContext.idempotency_key,
      attemptCount: emailLogAttemptCount(existingLog),
      attempt_count: emailLogAttemptCount(existingLog),
      emailLogId: existingLog?.id || null,
      emailQueueId: null,
      email_queue_id: null
    };
  }
  const queueRecord = await createEmailQueueRecord(message, deliveryContext, existingLog);
  const result = {
    to: lower(message.to || deliveryContext.recipient_email),
    from: clean(message.from || EMAIL_FROM),
    subject: clean(message.subject),
    text: "",
    html: "",
    accepted: false,
    provider: "resend",
    messageId: null,
    provider_id: null,
    status: "failed",
    delivery: "failed",
    errorCode,
    errorMessage,
    providerResponse: {},
    created_at: nowIso()
  };
  const logRecord = await recordEmailDelivery(result, deliveryContext, existingLog);
  const nextQueue = await patchEmailQueueRecord(queueRecord, emailQueuePatchAfterAttempt(result, logRecord, queueRecord, deliveryContext));
  return {
    ...result,
    event_type: deliveryContext.event_type || "email",
    email_type: deliveryContext.email_type || deliveryContext.event_type || "email",
    reservation_id: deliveryContext.reservation_id || null,
    restaurant_id: deliveryContext.restaurant_id || null,
    recipient_user_id: deliveryContext.recipient_user_id || null,
    locale: deliveryContext.locale,
    template_version: deliveryContext.template_version,
    idempotencyKey: deliveryContext.idempotency_key,
    idempotency_key: deliveryContext.idempotency_key,
    attemptCount: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
    attempt_count: logRecord?.attempt_count || emailLogAttemptCount(existingLog) + 1,
    emailLogId: logRecord?.id || existingLog?.id || null,
    emailQueueId: nextQueue?.id || queueRecord?.id || null,
    email_queue_id: nextQueue?.id || queueRecord?.id || null,
    queue_status: nextQueue?.status || "failed"
  };
}

function emailResultList(results = []) {
  return Array.isArray(results) ? results.filter(Boolean) : [results].filter(Boolean);
}

function emailDeliverySummary(results = []) {
  const list = emailResultList(results);
  return {
    provider: "resend",
    configured: emailService.configured,
    accepted_count: list.filter(isEmailAccepted).length,
    failed_count: list.filter((item) => item && !isEmailAccepted(item)).length,
    guest_confirmation_accepted: list.some((item) => item.event_type === "guest_request_received" && isEmailAccepted(item)),
    restaurant_notification_accepted: list.some((item) => item.event_type === "restaurant_request_notice" && isEmailAccepted(item)),
    admin_notification_accepted: list.some((item) => item.event_type === "admin_request_notice" && isEmailAccepted(item)),
    errors: list
      .filter((item) => item && !isEmailAccepted(item))
      .map((item) => ({
        event_type: item.event_type,
        recipient: item.to,
        status: item.status,
        errorCode: item.errorCode,
        errorMessage: item.errorMessage,
        attemptCount: item.attemptCount || item.attempt_count || null,
        duplicateSuppressed: Boolean(item.duplicate_suppressed),
        idempotencyKey: item.idempotencyKey || item.idempotency_key || null
      }))
  };
}

function emailDeliveryResult(result = null, provider = "other") {
  if (!result) {
    return {
      attempted: false,
      accepted: null,
      provider,
      messageId: null,
      errorCode: null,
      errorMessage: null
    };
  }
  return {
    attempted: true,
    accepted: isEmailAccepted(result) ? true : false,
    provider: result.provider || provider,
    messageId: result.messageId || result.provider_id || null,
    errorCode: result.errorCode || null,
    errorMessage: result.errorMessage ? "Email provider did not accept the message." : null,
    status: result.status || null,
    verifiedRejection: Boolean(!isEmailAccepted(result) && isPermanentEmailFailure(result.errorCode || result.status || "")),
    eventType: result.event_type || result.email_type || null
  };
}

function supabaseConfirmationEmailResult({ required = false, requested = false } = {}) {
  return {
    attempted: Boolean(required || requested),
    accepted: requested ? null : false,
    provider: "supabase",
    messageId: null,
    errorCode: requested ? null : (required ? "AUTH_CONFIRMATION_NOT_REQUESTED" : null),
    errorMessage: null,
    status: requested ? "requested" : (required ? "failed" : "not_required")
  };
}

function emailHtmlEscape(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function appEmailHtml(subject, body, cta = null, options = {}) {
  const brand = clean(options.brand || "SmartTable");
  const preheader = clean(options.preheader);
  const footer = clean(options.footer);
  const paragraphs = clean(body)
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => `<p>${emailHtmlEscape(line)}</p>`)
    .join("");
  const button = cta?.url
    ? `<p><a href="${emailHtmlEscape(cta.url)}" style="display:inline-block;margin-top:8px;padding:10px 14px;background:#0f735d;color:#ffffff;text-decoration:none;border-radius:8px;font-weight:700">${emailHtmlEscape(clean(cta.label || "Open SmartTable"))}</a></p>`
    : "";
  const preheaderHtml = preheader
    ? `<span style="display:none!important;visibility:hidden;opacity:0;color:transparent;height:0;width:0;overflow:hidden">${emailHtmlEscape(preheader)}</span>`
    : "";
  const footerHtml = footer
    ? `<p style="margin-top:24px;color:#68746f;font-size:13px;line-height:1.5">${emailHtmlEscape(footer)}</p>`
    : "";
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="color-scheme" content="light dark">
  <meta name="supported-color-schemes" content="light dark">
  <style>
    @media (prefers-color-scheme: dark) {
      .smarttable-email { background:#10261f !important; color:#e8f5ef !important; }
      .smarttable-card { background:#173d33 !important; color:#e8f5ef !important; border-color:#2f6354 !important; }
      .smarttable-muted { color:#bed3cb !important; }
    }
    @media screen and (max-width: 520px) {
      .smarttable-card { padding:20px !important; }
      .smarttable-title { font-size:22px !important; }
    }
  </style>
</head>
<body class="smarttable-email" style="margin:0;padding:0;background:#f4fbf8;color:#173d33">
${preheaderHtml}
<div style="display:none;max-height:0;overflow:hidden;color:transparent;opacity:0">SmartTable transactional email</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;background:#f4fbf8">
  <tr>
    <td align="center" style="padding:24px 12px">
      <table class="smarttable-card" role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border-collapse:collapse;max-width:640px;background:#ffffff;border:1px solid #d8ebe4;border-radius:12px;color:#173d33">
        <tr>
          <td style="padding:28px;font-family:Inter,Arial,sans-serif;line-height:1.55">
            <p aria-label="SmartTable logo" style="font-weight:900;letter-spacing:0;margin:0 0 18px;color:#0f735d;font-size:18px">${emailHtmlEscape(brand)}</p>
            <h1 class="smarttable-title" style="font-size:24px;line-height:1.25;margin:0 0 16px;font-weight:800">${emailHtmlEscape(subject)}</h1>
            <div style="font-size:15px">${paragraphs}${button}${footerHtml}</div>
            <p class="smarttable-muted" style="margin-top:28px;color:#68746f;font-size:12px;line-height:1.5">SmartTable sends transactional account and reservation emails only when needed to operate your account or reservation request.</p>
          </td>
        </tr>
      </table>
    </td>
  </tr>
</table>
</body>
</html>`;
}

function normalizeCommunicationChannel(value = "email") {
  const channel = clean(value).toLowerCase().replace(/[\s-]+/g, "_");
  return ["email", "sms", "in_app", "push"].includes(channel) ? channel : "email";
}

function normalizeConsentType(value = "marketing") {
  const type = clean(value).toLowerCase().replace(/[\s-]+/g, "_");
  return type === "transactional" ? "transactional" : "marketing";
}

function normalizeCommunicationConsentStatus(value = "revoked") {
  const status = clean(value).toLowerCase();
  return status === "granted" || status === "accepted" ? "granted" : "revoked";
}

function normalizePhoneE164(value = "", defaultCountry = "US") {
  const raw = clean(value);
  if (!raw) return "";
  if (raw.startsWith("+")) {
    const digits = raw.slice(1).replace(/\D/g, "");
    return digits.length >= 8 && digits.length <= 15 ? `+${digits}` : "";
  }
  const digits = raw.replace(/\D/g, "");
  if (defaultCountry === "US" && digits.length === 10) return `+1${digits}`;
  if (defaultCountry === "US" && digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  return digits.length >= 8 && digits.length <= 15 ? `+${digits}` : "";
}

function isValidE164Phone(value = "") {
  return /^\+[1-9]\d{7,14}$/.test(clean(value));
}

function hashPhoneValue(value = "") {
  return crypto.createHash("sha256").update(normalizePhoneE164(value)).digest("hex");
}

function phoneLast4(value = "") {
  return normalizePhoneE164(value).replace(/\D/g, "").slice(-4);
}

function maskPhoneValue(value = "") {
  const last4 = phoneLast4(value);
  return last4 ? `***-***-${last4}` : "";
}

function normalizeAlertStatus(value = "queued") {
  const status = clean(value).toLowerCase();
  return ["queued", "sent", "delivered", "acknowledged", "failed", "escalated"].includes(status) ? status : "queued";
}

function normalizePermissionStatus(value = "unknown") {
  const status = clean(value).toLowerCase();
  return ["granted", "denied", "prompt", "unknown"].includes(status) ? status : "unknown";
}

function normalizeDeviceType(value = "") {
  const type = clean(value).toLowerCase().replace(/[^a-z0-9_-]+/g, "_").slice(0, 40);
  return type || "browser";
}

function normalizeDeviceName(value = "") {
  return clean(value).replace(/[<>]/g, "").slice(0, 80) || "Restaurant device";
}

function endpointHash(endpoint = "") {
  return hashEmailValue(`push-endpoint:${clean(endpoint)}`);
}

function notificationLanguage(value = "") {
  const language = normalizeLanguage(value || "en");
  return ["en", "es", "hu"].includes(language) ? language : "en";
}

function defaultRestaurantNotificationPreferences(restaurantId = "") {
  return {
    restaurant_id: clean(restaurantId),
    dashboard_popup_enabled: true,
    sound_enabled: true,
    push_enabled: true,
    email_enabled: true,
    sms_fallback_enabled: false,
    primary_sms_number: "",
    escalation_sms_number: "",
    sms_fallback_delay_seconds: RESERVATION_ALERT_SMS_FALLBACK_SECONDS,
    sms_escalation_delay_seconds: RESERVATION_ALERT_ESCALATION_SECONDS,
    voice_call_enabled: false,
    voice_call_number: "",
    voice_call_delay_seconds: RESERVATION_ALERT_VOICE_DELAY_SECONDS,
    notification_language: "en"
  };
}

function clientRestaurantNotificationPreferences(preferences = {}) {
  return {
    restaurant_id: preferences.restaurant_id || "",
    dashboard_popup_enabled: preferences.dashboard_popup_enabled !== false,
    sound_enabled: preferences.sound_enabled !== false,
    push_enabled: preferences.push_enabled !== false,
    email_enabled: preferences.email_enabled !== false,
    sms_fallback_enabled: Boolean(preferences.sms_fallback_enabled),
    primary_sms_number: maskPhoneValue(preferences.primary_sms_number || ""),
    primary_sms_number_configured: Boolean(normalizePhoneE164(preferences.primary_sms_number || "")),
    escalation_sms_number: maskPhoneValue(preferences.escalation_sms_number || ""),
    escalation_sms_number_configured: Boolean(normalizePhoneE164(preferences.escalation_sms_number || "")),
    sms_fallback_delay_seconds: Number(preferences.sms_fallback_delay_seconds || RESERVATION_ALERT_SMS_FALLBACK_SECONDS),
    sms_escalation_delay_seconds: Number(preferences.sms_escalation_delay_seconds || RESERVATION_ALERT_ESCALATION_SECONDS),
    voice_call_enabled: Boolean(preferences.voice_call_enabled),
    voice_call_number: maskPhoneValue(preferences.voice_call_number || ""),
    voice_call_number_configured: Boolean(normalizePhoneE164(preferences.voice_call_number || "")),
    voice_call_delay_seconds: Number(preferences.voice_call_delay_seconds || RESERVATION_ALERT_VOICE_DELAY_SECONDS),
    notification_language: notificationLanguage(preferences.notification_language || "en")
  };
}

function normalizeNotificationPreferencePatch(body = {}, restaurantId = "") {
  const fallback = defaultRestaurantNotificationPreferences(restaurantId);
  const patch = { restaurant_id: restaurantId };
  for (const key of ["dashboard_popup_enabled", "sound_enabled", "push_enabled", "email_enabled", "sms_fallback_enabled", "voice_call_enabled"]) {
    if (body[key] !== undefined) patch[key] = boolValue(body[key]);
  }
  if (body.primary_sms_number !== undefined && clean(body.primary_sms_number)) {
    const phone = normalizePhoneE164(body.primary_sms_number);
    if (!phone) {
      const error = new Error("Primary SMS number must be a valid E.164 phone number.");
      error.status = 400;
      throw error;
    }
    patch.primary_sms_number = phone;
  }
  if (body.escalation_sms_number !== undefined && clean(body.escalation_sms_number)) {
    const phone = normalizePhoneE164(body.escalation_sms_number);
    if (!phone) {
      const error = new Error("Escalation SMS number must be a valid E.164 phone number.");
      error.status = 400;
      throw error;
    }
    patch.escalation_sms_number = phone;
  }
  if (body.voice_call_number !== undefined && clean(body.voice_call_number)) {
    const phone = normalizePhoneE164(body.voice_call_number);
    if (!phone) {
      const error = new Error("Voice call number must be a valid E.164 phone number.");
      error.status = 400;
      throw error;
    }
    patch.voice_call_number = phone;
  }
  if (body.sms_fallback_delay_seconds !== undefined) {
    patch.sms_fallback_delay_seconds = Math.max(15, Math.min(3600, Math.trunc(Number(body.sms_fallback_delay_seconds) || fallback.sms_fallback_delay_seconds)));
  }
  if (body.sms_escalation_delay_seconds !== undefined || body.escalation_delay_seconds !== undefined) {
    patch.sms_escalation_delay_seconds = Math.max(60, Math.min(86400, Math.trunc(Number(body.sms_escalation_delay_seconds || body.escalation_delay_seconds) || fallback.sms_escalation_delay_seconds)));
  }
  if (body.voice_call_delay_seconds !== undefined) {
    patch.voice_call_delay_seconds = Math.max(60, Math.min(86400, Math.trunc(Number(body.voice_call_delay_seconds) || fallback.voice_call_delay_seconds)));
  }
  if (body.notification_language !== undefined) patch.notification_language = notificationLanguage(body.notification_language);
  return patch;
}

function reservationAlertPayload(row = {}) {
  const reservationId = row.reservation_id || row.id || "";
  const restaurantId = row.restaurant_id || "";
  const standardReservation = isStandardReservation(row);
  const discountPercent = standardReservation ? null : Number(row.discount_percent || row.discount_value || row.discount || 0);
  return {
    reservation_id: reservationId,
    restaurant_id: restaurantId,
    restaurant_name: clean(row.restaurant_name || row.name || "Restaurant"),
    reservation_date: clean(row.reservation_date || row.offer_date),
    reservation_time: clean(row.reservation_time || row.offer_time || row.start_time),
    party_size: Number(row.party_size || 0),
    offer_title: clean(row.offer_title || row.title || row.title_en || (standardReservation ? standardReservationLabel(row.guest_language || "en") : "SmartTable offer")),
    discount_percent: discountPercent,
    discount_label: standardReservation ? standardReservationLabel(row.guest_language || "en") : `${discountPercent || 0}% off`,
    reservation_type: standardReservation ? "standard" : "discount_offer",
    reference: clean(row.reference || ""),
    dashboard_url: `${PUBLIC_BASE_URL}/partner/reservations?reservation=${encodeURIComponent(clean(row.reference || reservationId))}`,
    created_at: clean(row.created_at || nowIso())
  };
}

function clientReservationAlert(row = {}) {
  const payload = row.safe_payload || row.payload || {};
  const createdAt = row.created_at || payload.created_at || nowIso();
  return {
    id: row.id,
    reservation_id: row.reservation_id || payload.reservation_id,
    restaurant_id: row.restaurant_id || payload.restaurant_id,
    status: normalizeAlertStatus(row.status),
    alert_type: row.alert_type || "new_reservation_request",
    priority: row.priority || "high",
    acknowledged_at: row.acknowledged_at || null,
    created_at: createdAt,
    waiting_seconds: Math.max(0, Math.round((Date.now() - new Date(createdAt).getTime()) / 1000)),
    payload: {
      restaurant_name: payload.restaurant_name || row.restaurant_name || "Restaurant",
      reservation_date: payload.reservation_date || row.reservation_date || "",
      reservation_time: payload.reservation_time || row.reservation_time || "",
      party_size: Number(payload.party_size || row.party_size || 0),
      offer_title: payload.offer_title || row.offer_title || "SmartTable offer",
      discount_percent: payload.discount_percent === null ? null : Number(payload.discount_percent || row.discount_percent || 0),
      discount_label: payload.discount_label || (payload.reservation_type === "standard" ? standardReservationLabel("en") : `${Number(payload.discount_percent || row.discount_percent || 0)}% off`),
      reservation_type: payload.reservation_type || normalizeReservationType(row.reservation_type, row.offer_id),
      reference: payload.reference || row.reference || "",
      dashboard_url: safeInternalApiUrl(payload.dashboard_url || `/partner/reservations?reservation=${encodeURIComponent(payload.reference || row.reference || "")}`)
    }
  };
}

function clientReservationAlertDelivery(row = {}) {
  return {
    id: row.id,
    alert_id: row.alert_id || "",
    restaurant_id: row.restaurant_id || "",
    reservation_id: row.reservation_id || "",
    channel: row.channel || "",
    provider: row.provider || "",
    status: normalizeAlertStatus(row.status || "queued"),
    provider_message_id: clean(row.provider_message_id || "").slice(0, 120),
    error_code: clean(row.error_code || "").slice(0, 80),
    error_message_safe: clean(row.error_message_safe || "").slice(0, 240),
    attempt_number: Number(row.attempt_number || 1),
    created_at: row.created_at || null,
    sent_at: row.sent_at || null,
    delivered_at: row.delivered_at || null,
    acknowledged_at: row.acknowledged_at || null
  };
}

function safeInternalApiUrl(value = "") {
  const raw = clean(value);
  if (/^\/(?!\/)/.test(raw)) return raw;
  try {
    const parsed = new URL(raw);
    const base = new URL(PUBLIC_BASE_URL);
    if (parsed.origin !== base.origin) return `${parsed.pathname}${parsed.search}${parsed.hash}`;
    return `${parsed.pathname}${parsed.search}${parsed.hash}`;
  } catch {
    return "/partner/reservations";
  }
}

function normalizeDestination(value = "", channel = "email") {
  const destination = clean(value);
  return normalizeCommunicationChannel(channel) === "email" ? lower(destination) : normalizePhoneE164(destination);
}

function communicationPreferenceDefaults(profile = {}) {
  return {
    user_id: clean(profile.id),
    transactional_email_enabled: true,
    marketing_email_enabled: false,
    transactional_sms_enabled: false,
    marketing_sms_enabled: false,
    in_app_enabled: true,
    preferred_language: normalizeLanguage(profile.preferred_language || "en"),
    timezone: clean(profile.timezone || "America/New_York"),
    updated_at: nowIso()
  };
}

function sanitizeCommunicationPreference(row = {}, profile = {}) {
  const defaults = communicationPreferenceDefaults(profile);
  return {
    user_id: clean(row.user_id || defaults.user_id),
    transactional_email_enabled: row.transactional_email_enabled !== false,
    marketing_email_enabled: Boolean(row.marketing_email_enabled),
    transactional_sms_enabled: Boolean(row.transactional_sms_enabled),
    marketing_sms_enabled: Boolean(row.marketing_sms_enabled),
    in_app_enabled: row.in_app_enabled !== false,
    preferred_language: normalizeLanguage(row.preferred_language || defaults.preferred_language),
    timezone: clean(row.timezone || defaults.timezone),
    updated_at: row.updated_at || defaults.updated_at
  };
}

function sanitizeCommunicationConsent(row = {}) {
  return {
    id: clean(row.id),
    user_id: clean(row.user_id),
    channel: normalizeCommunicationChannel(row.channel),
    consent_type: normalizeConsentType(row.consent_type),
    status: normalizeCommunicationConsentStatus(row.status),
    source: clean(row.source || "account_preferences"),
    consent_text_version: clean(row.consent_text_version || COMMUNICATION_CONSENT_VERSION),
    granted_at: row.granted_at || null,
    revoked_at: row.revoked_at || null,
    created_at: row.created_at || null
  };
}

function communicationConsentAuditPayload({ profile, channel, consentType, status, source, headers = {} }) {
  const normalizedStatus = normalizeCommunicationConsentStatus(status);
  const now = nowIso();
  return {
    id: crypto.randomUUID(),
    user_id: profile.id,
    channel: normalizeCommunicationChannel(channel),
    consent_type: normalizeConsentType(consentType),
    status: normalizedStatus,
    source: clean(source || "account_preferences"),
    consent_text_version: COMMUNICATION_CONSENT_VERSION,
    ip_address: maskedIpAddress(clientIpAddress(headers)),
    user_agent: summarizeUserAgent(headerValue(headers, "user-agent")),
    granted_at: normalizedStatus === "granted" ? now : null,
    revoked_at: normalizedStatus === "revoked" ? now : null,
    created_at: now
  };
}

async function getCommunicationPreferencesForProfile(profile = {}, { create = true } = {}) {
  if (!profile?.id) return sanitizeCommunicationPreference({}, profile);
  if (!supabaseConfigured) {
    ensureDemo();
    let row = demo.communicationPreferences.find((item) => item.user_id === profile.id);
    if (!row && create) {
      row = communicationPreferenceDefaults(profile);
      demo.communicationPreferences.unshift(row);
    }
    return sanitizeCommunicationPreference(row || {}, profile);
  }
  const rows = await supabaseFetch(`/rest/v1/communication_preferences?select=*&user_id=eq.${encodeURIComponent(profile.id)}&limit=1`, { service: true }).catch(() => []);
  if (rows?.[0] || !create) return sanitizeCommunicationPreference(rows?.[0] || {}, profile);
  const created = await supabaseFetch("/rest/v1/communication_preferences?on_conflict=user_id&select=*", {
    method: "POST",
    service: true,
    headers: { Prefer: "resolution=merge-duplicates,return=representation" },
    body: communicationPreferenceDefaults(profile)
  }).catch(() => []);
  return sanitizeCommunicationPreference(created?.[0] || {}, profile);
}

async function getCommunicationConsentHistoryForProfile(profile = {}) {
  if (!profile?.id) return [];
  if (!supabaseConfigured) {
    ensureDemo();
    return demo.communicationConsents
      .filter((item) => item.user_id === profile.id)
      .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
      .map(sanitizeCommunicationConsent);
  }
  const rows = await supabaseFetch(`/rest/v1/communication_consents?select=*&user_id=eq.${encodeURIComponent(profile.id)}&order=created_at.desc&limit=100`, { service: true }).catch(() => []);
  return (rows || []).map(sanitizeCommunicationConsent);
}

async function recordCommunicationConsentEvent({ profile, channel = "email", consentType = "marketing", status = "revoked", source = "account_preferences", headers = {} }) {
  if (!profile?.id) return null;
  const payload = communicationConsentAuditPayload({ profile, channel, consentType, status, source, headers });
  if (!supabaseConfigured) {
    ensureDemo();
    demo.communicationConsents.unshift(payload);
    return sanitizeCommunicationConsent(payload);
  }
  if (!(await supabaseTableExists("communication_consents"))) return null;
  const rows = await supabaseFetch("/rest/v1/communication_consents?select=*", {
    method: "POST",
    service: true,
    headers: { Prefer: "return=representation" },
    body: await filterSupabaseTablePayload("communication_consents", payload)
  });
  return sanitizeCommunicationConsent(rows?.[0] || payload);
}

async function updateCommunicationPreferencesForProfile(profile = {}, body = {}, headers = {}) {
  const current = await getCommunicationPreferencesForProfile(profile, { create: true });
  const next = {
    ...current,
    transactional_email_enabled: body.transactional_email_enabled === undefined ? current.transactional_email_enabled : boolValue(body.transactional_email_enabled),
    marketing_email_enabled: body.marketing_email_enabled === undefined ? current.marketing_email_enabled : boolValue(body.marketing_email_enabled),
    transactional_sms_enabled: body.transactional_sms_enabled === undefined ? current.transactional_sms_enabled : boolValue(body.transactional_sms_enabled),
    marketing_sms_enabled: body.marketing_sms_enabled === undefined ? current.marketing_sms_enabled : boolValue(body.marketing_sms_enabled),
    in_app_enabled: body.in_app_enabled === undefined ? current.in_app_enabled : boolValue(body.in_app_enabled),
    preferred_language: normalizeLanguage(body.preferred_language || body.language || current.preferred_language),
    timezone: clean(body.timezone || current.timezone || "America/New_York"),
    updated_at: nowIso()
  };
  if (!supabaseConfigured) {
    ensureDemo();
    const index = demo.communicationPreferences.findIndex((item) => item.user_id === profile.id);
    if (index >= 0) demo.communicationPreferences[index] = next;
    else demo.communicationPreferences.unshift(next);
  } else if (await supabaseTableExists("communication_preferences")) {
    await supabaseFetch("/rest/v1/communication_preferences?on_conflict=user_id", {
      method: "POST",
      service: true,
      headers: { Prefer: "resolution=merge-duplicates,return=minimal" },
      body: await filterSupabaseTablePayload("communication_preferences", next)
    });
  }
  const events = [];
  if (next.marketing_email_enabled !== current.marketing_email_enabled) {
    events.push(await recordCommunicationConsentEvent({
      profile,
      channel: "email",
      consentType: "marketing",
      status: next.marketing_email_enabled ? "granted" : "revoked",
      source: clean(body.source || "account_preferences"),
      headers
    }));
  }
  if (next.marketing_sms_enabled !== current.marketing_sms_enabled) {
    events.push(await recordCommunicationConsentEvent({
      profile,
      channel: "sms",
      consentType: "marketing",
      status: next.marketing_sms_enabled ? "granted" : "revoked",
      source: clean(body.source || "account_preferences"),
      headers
    }));
  }
  if (next.transactional_sms_enabled !== current.transactional_sms_enabled) {
    events.push(await recordCommunicationConsentEvent({
      profile,
      channel: "sms",
      consentType: "transactional",
      status: next.transactional_sms_enabled ? "granted" : "revoked",
      source: clean(body.source || "account_preferences"),
      headers
    }));
  }
  return {
    preferences: sanitizeCommunicationPreference(next, profile),
    consent_events: events.filter(Boolean)
  };
}

async function guestCommunications(method, body, headers) {
  const { profile } = await requireProfile(headers, ["guest"]);
  if (method === "GET") {
    const [preferences, consents] = await Promise.all([
      getCommunicationPreferencesForProfile(profile, { create: true }),
      getCommunicationConsentHistoryForProfile(profile)
    ]);
    return json(200, { mode: supabaseConfigured ? "supabase" : "demo", preferences, consents });
  }
  if (method !== "PATCH") return json(405, { error: "Method not allowed." });
  const result = await updateCommunicationPreferencesForProfile(profile, body, headers);
  return json(200, { mode: supabaseConfigured ? "supabase" : "demo", ...result });
}

async function isSuppressedDestination(destination = "", channel = "email") {
  const normalized = normalizeDestination(destination, channel);
  if (!normalized) return false;
  if (!supabaseConfigured) {
    ensureDemo();
    return demo.suppressionList.some((item) => item.normalized_destination === normalized && normalizeCommunicationChannel(item.channel) === normalizeCommunicationChannel(channel));
  }
  const rows = await supabaseFetch(`/rest/v1/suppression_list?select=id&normalized_destination=eq.${encodeURIComponent(normalized)}&channel=eq.${encodeURIComponent(normalizeCommunicationChannel(channel))}&limit=1`, { service: true }).catch(() => []);
  return Boolean(rows?.[0]);
}

function latestConsentAllowsMarketing(consents = [], channel = "email") {
  const normalizedChannel = normalizeCommunicationChannel(channel);
  const latest = [...(consents || [])]
    .filter((item) => normalizeCommunicationChannel(item.channel) === normalizedChannel && normalizeConsentType(item.consent_type) === "marketing")
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))[0];
  return latest ? normalizeCommunicationConsentStatus(latest.status) === "granted" : false;
}

async function marketingAllowedForProfile(profile = {}, destination = "", channel = "email") {
  const normalizedChannel = normalizeCommunicationChannel(channel);
  const normalizedDestination = normalizeDestination(destination, normalizedChannel);
  const validDestination = normalizedChannel === "email"
    ? isValidSignupEmail(normalizedDestination)
    : normalizedChannel === "sms"
      ? isValidE164Phone(normalizedDestination)
      : Boolean(normalizedDestination);
  if (!profile?.id || !validDestination) return { allowed: false, reason: "missing_valid_recipient" };
  if (await isSuppressedDestination(normalizedDestination, normalizedChannel)) return { allowed: false, reason: "suppressed" };
  const [preferences, consents] = await Promise.all([
    getCommunicationPreferencesForProfile(profile, { create: false }),
    getCommunicationConsentHistoryForProfile(profile)
  ]);
  const preferenceAllows = normalizedChannel === "email"
    ? Boolean(preferences.marketing_email_enabled)
    : normalizedChannel === "sms"
      ? Boolean(preferences.marketing_sms_enabled)
      : false;
  if (!preferenceAllows) return { allowed: false, reason: "marketing_preference_disabled" };
  if (!latestConsentAllowsMarketing(consents, normalizedChannel)) return { allowed: false, reason: "marketing_consent_missing" };
  return { allowed: true, reason: "eligible" };
}

function campaignStatus(value = "draft") {
  const status = clean(value).toLowerCase().replace(/[\s-]+/g, "_");
  return ["draft", "scheduled", "queued", "sending", "sent", "cancelled", "failed", "archived"].includes(status) ? status : "draft";
}

function sanitizeCampaignText(value = "", maxLength = 12000) {
  return clean(value)
    .replace(/\u0000/g, "")
    .replace(/<\s*(script|style|iframe|object|embed|form|input|button|meta|link)[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, "")
    .replace(/<\s*(script|style|iframe|object|embed|form|input|button|meta|link)[^>]*\/?\s*>/gi, "")
    .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
    .replace(/\bjavascript\s*:/gi, "")
    .replace(/\bdata\s*:\s*text\/html/gi, "")
    .slice(0, maxLength);
}

function campaignTemplateVariables(...values) {
  const names = new Set();
  for (const value of values) {
    const text = clean(value);
    const matches = text.matchAll(/\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g);
    for (const match of matches) names.add(clean(match[1]).toLowerCase());
  }
  return [...names];
}

function disallowedCampaignTemplateVariables(campaign = {}) {
  const variables = campaignTemplateVariables(
    campaign.subject_en,
    campaign.subject_es,
    campaign.subject_hu,
    campaign.preheader_en,
    campaign.preheader_es,
    campaign.preheader_hu,
    campaign.title_en,
    campaign.title_es,
    campaign.title_hu,
    campaign.body_en,
    campaign.body_es,
    campaign.body_hu
  );
  return variables.filter((name) => !CAMPAIGN_TEMPLATE_VARIABLE_ALLOWLIST.has(name));
}

function validateCampaignTemplateVariables(campaign = {}) {
  const disallowed = disallowedCampaignTemplateVariables(campaign);
  if (!disallowed.length) return "";
  return `Unsupported template variable: ${disallowed.slice(0, 3).join(", ")}.`;
}

function marketingComplianceFooter(language = "en") {
  const preferencesUrl = `${PUBLIC_BASE_URL}/account/notifications`;
  const unsubscribeUrl = `${preferencesUrl}?unsubscribe=marketing`;
  const footerByLanguage = {
    en: [
      `Manage communication preferences: ${preferencesUrl}`,
      `Unsubscribe from marketing emails: ${unsubscribeUrl}`,
      `Business mailing address: ${BUSINESS_MAILING_ADDRESS}`
    ],
    es: [
      `Gestiona tus preferencias de comunicacion: ${preferencesUrl}`,
      `Darte de baja de emails de marketing: ${unsubscribeUrl}`,
      `Direccion postal comercial: ${BUSINESS_MAILING_ADDRESS}`
    ],
    hu: [
      `Kommunikacios beallitasok kezelese: ${preferencesUrl}`,
      `Leiratkozas marketing emailekrol: ${unsubscribeUrl}`,
      `Uzleti levelezesi cim: ${BUSINESS_MAILING_ADDRESS}`
    ]
  };
  return footerByLanguage[normalizeLanguage(language)] || footerByLanguage.en;
}

function marketingEmailFooterText(language = "en") {
  return marketingComplianceFooter(language).join("\n");
}

function campaignPayloadFromBody(body = {}, restaurant = null, profile = {}, mode = "partner") {
  const audience = jsonFrom(body.audience_definition, {});
  const channel = normalizeCommunicationChannel(body.channel || "email");
  const offerId = clean(body.offer_id || audience.offer_id);
  const audienceSource = clean(body.audience_source || body.source || audience.source).toLowerCase();
  const offerUrl = audienceSource === "favorite_offer_alert"
    ? safeCampaignOfferUrl(body.offer_url || audience.offer_url, restaurant || {}, offerId)
    : "";
  const payload = {
    restaurant_id: restaurant?.id || nullableClean(body.restaurant_id),
    created_by: profile.id,
    campaign_type: mode === "admin" && !restaurant?.id ? "admin_broadcast" : "partner_marketing",
    channel: channel === "email" ? "email" : "email",
    name: sanitizeCampaignText(body.name || body.campaign_name || body.subject_en || "Untitled campaign", 160),
    subject_en: sanitizeCampaignText(body.subject_en || body.subject || "", 180),
    subject_es: sanitizeCampaignText(body.subject_es || "", 180),
    subject_hu: sanitizeCampaignText(body.subject_hu || "", 180),
    preheader_en: sanitizeCampaignText(body.preheader_en || body.preheader || "", 220),
    preheader_es: sanitizeCampaignText(body.preheader_es || "", 220),
    preheader_hu: sanitizeCampaignText(body.preheader_hu || "", 220),
    body_en: sanitizeCampaignText(body.body_en || body.body || "", 12000),
    body_es: sanitizeCampaignText(body.body_es || "", 12000),
    body_hu: sanitizeCampaignText(body.body_hu || "", 12000),
    audience_definition: {
      followers: body.audience_followers === undefined ? audience.followers !== false : boolValue(body.audience_followers),
      reservations: body.audience_reservations === undefined ? audience.reservations !== false : boolValue(body.audience_reservations),
      restaurant_subscribers: body.audience_subscribers === undefined ? Boolean(audience.restaurant_subscribers) : boolValue(body.audience_subscribers),
      offer_id: offerId,
      filters: jsonFrom(body.filters, audience.filters || {}),
      ...(audienceSource === "favorite_offer_alert" ? {
        source: "favorite_offer_alert",
        offer_url: offerUrl
      } : {})
    },
    scheduled_at: nullableClean(body.scheduled_at),
    status: campaignStatus(body.status || "draft"),
    template_variable_allowlist: [...CAMPAIGN_TEMPLATE_VARIABLE_ALLOWLIST],
    xss_sanitized_at: nowIso(),
    updated_at: nowIso()
  };
  if (!payload.name) payload.name = "Untitled campaign";
  return payload;
}

function validateCampaignForSending(campaign = {}) {
  if (!clean(campaign.name)) return "Campaign name is required.";
  if (!clean(campaign.subject_en || campaign.subject_es || campaign.subject_hu)) return "At least one subject is required.";
  if (!clean(campaign.body_en || campaign.body_es || campaign.body_hu)) return "At least one body is required.";
  const variableError = validateCampaignTemplateVariables(campaign);
  if (variableError) return variableError;
  return "";
}

function sanitizeCampaignForClient(campaign = {}, recipients = []) {
  const recipientRows = Array.isArray(recipients) ? recipients : [];
  const counts = recipientRows.reduce((acc, row) => {
    const status = clean(row.status || "queued");
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  return {
    id: campaign.id,
    restaurant_id: campaign.restaurant_id || null,
    created_by: campaign.created_by || null,
    campaign_type: campaign.campaign_type || "partner_marketing",
    channel: campaign.channel || "email",
    name: campaign.name || "",
    subject_en: campaign.subject_en || "",
    subject_es: campaign.subject_es || "",
    subject_hu: campaign.subject_hu || "",
    preheader_en: campaign.preheader_en || "",
    preheader_es: campaign.preheader_es || "",
    preheader_hu: campaign.preheader_hu || "",
    body_en: campaign.body_en || "",
    body_es: campaign.body_es || "",
    body_hu: campaign.body_hu || "",
    audience_definition: campaign.audience_definition || {},
    scheduled_at: campaign.scheduled_at || null,
    status: campaignStatus(campaign.status),
    recipient_count: Number(campaign.recipient_count || recipientRows.length || 0),
    sent_count: Number(campaign.sent_count || counts.sent || 0),
    delivered_count: Number(campaign.delivered_count || counts.delivered || 0),
    failed_count: Number(campaign.failed_count || counts.failed || counts.bounced || counts.complained || 0),
    opened_count: Number(campaign.opened_count || counts.opened || 0),
    clicked_count: Number(campaign.clicked_count || counts.clicked || 0),
    created_at: campaign.created_at || null,
    updated_at: campaign.updated_at || null,
    recipients: recipientRows.slice(0, 50).map((row) => ({
      id: row.id,
      channel: row.channel || "email",
      destination_hash: row.destination_hash || "",
      language: normalizeLanguage(row.language || "en"),
      status: clean(row.status || "queued"),
      provider_message_id: row.provider_message_id || null,
      queued_at: row.queued_at || null,
      sent_at: row.sent_at || null,
      delivered_at: row.delivered_at || null,
      failed_at: row.failed_at || null,
      failure_reason: row.failure_reason || null,
      opened_at: row.opened_at || null,
      clicked_at: row.clicked_at || null
    }))
  };
}

