function parseSenderAddress(value = "") {
  const input = clean(value);
  const match = input.match(/^(.*?)<([^>]+)>$/);
  if (match) return { name: clean(match[1]).replace(/^"|"$/g, ""), email: lower(match[2]) };
  return { name: "", email: lower(input) };
}

